(window.GIM_TP=window.GIM_TP||{})["Pesachim.1"]={"from":220,"a":[[["דמסוכר ולא משי ידיה מפחיד שבעה יומי דשקיל מזייה ולא משי ידיה מפחיד תלתא יומי דשקיל טופריה ולא משי ידיה מפחיד חד יומא ולא ידע מאי קא מפחיד ידא אאוסיא דרגא לפחדא ידא אפותא דרגא לשינתא","תנא אוכלין ומשקין תחת המטה אפילו מחופין בכלי ברזל רוח רעה שורה עליהן ת\"ר לא ישתה אדם מים לא בלילי רביעיות ולא בלילי שבתות ואם שתה דמו בראשו מפני סכנה מאי סכנה רוח רעה","ואם צחי מאי תקנתיה (נימא) שבעה קולות שאמר דוד על המים והדר נישתי שנאמר (תהלים כט, ג) קול ה' על המים אל הכבוד הרעים ה' על מים רבים קול ה' בכח קול ה' בהדר קול ה' שובר ארזים וישבר ה' את ארזי הלבנון קול ה' חוצב להבות אש קול ה' יחיל מדבר יחיל ה' מדבר קדש קול ה' יחולל אילות ויחשוף יערות ובהיכלו כולו אומר כבוד","ואי לא (נימא) הכי לול שפן אניגרון אנירדפין בין כוכבי יתיבנא בין בליעי שמיני אזילנא ואי לא אי איכא איניש בהדיה ניתעריה ולימא ליה פלניא בר פלנתא צחינא מיא והדר נישתי ואי לא מקרקש נכתמא אחצבא והדר נישתי ואי לא נישדי בה מידי והדר נישתי","ת\"ר לא ישתה אדם מים לא מן הנהרות ולא מן האגמים בלילה ואם שתה דמו בראשו מפני הסכנה מאי סכנה סכנת שברירי ואי צחי מאי תקנתיה אי איכא איניש בהדיה לימא ליה פלניא בר פלנתא צחינא מיא ואי לא (נימא) איהו לנפשיה פלניא אמרה לי אימי איזדהר משברירי שברירי ברירי רירי ירי רי צחינא מיא בכסי חיורי:","ואפילו מן התמחוי וכו': פשיטא","לא נצרכא אלא אפילו לר\"ע דאמר עשה שבתך חול ואל תצטרך לבריות הכא משום פרסומי ניסא (מודי)","תנא דבי אליהו אע\"פ שאמר ר\"ע עשה שבתך חול ואל תצטרך לבריות אבל עושה הוא דבר מועט בתוך ביתו מאי נינהו אמר רב פפא כסא דהרסנא כדתנן ר' יהודה בן תימא אומר הוי עז כנמר וקל כנשר רץ כצבי וגבור כארי לעשות רצון אביך שבשמים","ת\"ר שבעה דברים צוה ר\"ע את רבי יהושע בנו בני אל תשב בגובהה של עיר ותשנה ואל תדור בעיר שראשיה תלמידי חכמים","ואל תכנס לביתך פתאום כ\"ש לבית חבירך ואל תמנע מנעלים מרגליך השכם ואכול בקיץ מפני החמה ובחורף מפני הצינה ועשה שבתך חול ואל תצטרך לבריות והוי משתדל עם אדם שהשעה משחקת לו","אמר רב פפא לא למיזבן מיניה ולא לזבוני ליה אלא למעבד שותפות בהדיה והשתא דאמר רב שמואל בר יצחק מאי דכתיב (איוב א, י) מעשה ידיו ברכת כל הנוטל פרוטה מאיוב מתברך אפילו למיזבן מיניה ולזבוני ליה שפיר דמי","חמשה דברים צוה ר\"ע את רבי שמעון בן יוחי כשהיה חבוש בבית האסורין אמר לו רבי למדני תורה אמר איני מלמדך אמר לו אם אין אתה מלמדני אני אומר ליוחי אבא ומוסרך למלכות אמר לו בני יותר ממה שהעגל רוצה לינק פרה רוצה להניק אמר לו ומי בסכנה והלא עגל בסכנה","אמר לו אם בקשת ליחנק היתלה באילן גדול וכשאתה מלמד את בנך למדהו בספר מוגה מאי היא אמר רבא ואיתימא רב משרשיא בחדתא שבשתא כיון דעל על","לא תבשל בקדירה שבישל בה חבירך מאי ניהו גרושה בחיי בעלה דאמר מר גרוש שנשא גרושה ארבע דעות במטה ואי בעית אימא אפילו באלמנה לפי"],[[0,"דמסוכר","מקיז דם מן הכתפיים לשון סיכורי:"],[0,"ידא אאוסיא","שרגיל להניח ידו אצל נחיריו על שפתיו:"],[0,"דרגא לפחדא","דרך הוא להביא לו פחד רוח רעה:"],[3,"לול שפן אניגרון אנירדפי","לחש הוא:"],[3,"בי בליעי ושמיני","הנה סביבותי אנשים כחושים ושמנים ותניחוני:"],[3,"ונימא ליה","צחינא מיא:"],[7,"הוי עז","התחזק במצוה יותר משיכולת בידך:"],[8,"אל תשב בגובהה של עיר ותשנה","מקום שבני העיר עוברים ושבין שמא כשהן עוברין ושבין יבטלוך ויפסיקוך ממשנתך:"],[8,"ואל תדור בעיר שראשיה תלמידי חכמים","דטרוד בגרסיה ולא במילי דציבורא:"],[10,"לא למיזבן מיניה ולא לזבוני ליה","דאיידי דעדיף מזליה נצח וזכי ליה להאי:"],[11,"אמר ליה ר\"ש בן יוחי ומי בסכנה","והלא העגל בסכנה ומה לך בכך:"],[12,"אם בקשת ליחנק","לומר דבר שיהיה נשמע לבריות ויקבלו ממך:"],[12,"היתלה באילן גדול","אמור בשם אדם גדול:"],[12,"בחדתא","כשהתינוק למד בחדש כשהוא מתחיל ללמוד:"]],[[8,"צוה רבי עקיבא את רבי יהושע בנו","פירש רשב\"ם דהוא ר' יהושע בן קרחה דר\"ע קרח היה כדאמרינן [בבכורות] (דף נח.) שהיה בן עזאי אומר כל חכמי ישראל דומין לפני כקליפת השום חוץ מן הקרח הזה ואין נראה שיהיה הגמרא קורא אותו בן קרחה דרך גנאי שהרי נענשו הנערים שקראו לאלישע עלה קרח (מלכים ב ב׳:כ״ג) ובן עזאי קראו כן דרך בדיחותא:"],[12,"שבשתא דעל על","תימה דרבא גופא אית ליה בלא יחפור (ב\"ב דף כא.) שבשתא ממילא נפקא ויש לומר דהיינו כשלומד קמי דגריס ולא דייק שיכול להבין מעצמו כשיגדל אבל כאן דאיירי בספר שאינו מוגה סומך על ספרו ואינו יוצא מידי טעותו:"]]],[["שאין כל אצבעות שוות","מצוה וגוף גדול אוכל פירות ולא שכר מצוה וגוף טהור נושא אשה ולו בנים","ארבעה דברים צוה רבינו הקדוש את בניו אל תדור בשכנציב משום דליצני הוו ומשכו לך בליצנותא","ואל תשב על מטת ארמית איכא דאמרי דלא תיגני בלא קרית שמע ואיכא דאמרי דלא תינסב גיורתא","ואיכא דאמרי ארמאית ממש ומשום מעשה דרב פפא","ואל תבריח עצמך מן המכס דילמא משכחו לך ושקלי מנך כל דאית לך ואל תעמוד בפני השור בשעה שעולה מן האגם מפני שהשטן מרקד בין קרניו אמר רבי שמואל בשור שחור וביומי ניסן","תני רב אושעיא מרחיקין משור תם חמשים אמה משור מועד כמלא עיניו","תנא משמיה דרבי מאיר ריש תורא בדיקולא סק לאיגרא ושדי דרגא מתותך אמר רב ניזהא דתורא הן הן ניזהא דאריה זה זה ניזהא דגמלא דא דא ניזהא דארבא הילני הייא הילא והילוק הוליא","אמר אביי עור דג וכוס חמין וביצים וכנים לבנים כולן קשין לדבר אחר עור מאן דגני אמשכא דצלא דג שיבוטא ביומי ניסן כוס שיורי כסא דהרסנא חמין חמימי דחמימי משדרו עילויה ביצים מאן דמדרך אקליפים כינים לבנים מאן דמחוור לבושיה ולא נטיר ליה תמניא יומי והדר לבוש לה בריין הנך כינים וקשין לדבר אחר","אמר רב פפא ביתא דאית ביה שונרא לא ניעול בה איניש בלא מסני מאי טעמא משום דשונרא קטיל לחיויא ואכיל ליה ואית ביה בחיויא גרמי קטיני ואי יתיב לה גרמא דחיויא אכרעיה לא נפיק ואסתכן ליה איכא דאמרי ביתא דלית ביה שונרא לא ניעול ביה איניש בהכרא מאי טעמא דילמא מיכריך ביה חויא ולא ידע ומסתכן","ג' דברים צוה ר' ישמעאל בר' יוסי את רבי (מק\"ש סימן) אל תעש מום בעצמך מאי היא לא תיהוי לך דינא בהדי תלתא דחד הוי בעל דינך ותרי סהדי ואל תעמוד על המקח בשעה שאין לך דמים","אשתך טבלה אל תזקק לה לילה הראשונה אמר רב ובנדה דאורייתא הואיל והוחזק מעין פתוח דילמא משכה זיבה","שלשה דברים צוה רבי יוסי בר' יהודה את רבי אל תצא יחידי בלילה ואל תעמוד בפני הנר ערום ואל תכנס למרחץ חדש שמא תפחת עד כמה אריב\"ל עד י\"ב חדש ואל תעמוד בפני הנר ערום דתניא העומד בפני הנר ערום הוי נכפה והמשמש מטתו לאור הנר הויין לו בנים נכפין","ת\"ר המשמש מטתו על מטה שתינוק ישן עליה אותו תינוק נכפה ולא אמרן אלא דלא הוי בר שתא אבל הוי בר שתא לית לן בה ולא אמרן אלא דגני להדי כרעיה אבל גני להדי רישיה לית לן בה ולא אמרן אלא דלא מנח ידיה עילויה אבל מנח ידיה עילויה לית לן בה","אל תצא יחידי בלילה דתניא לא יצא יחידי בלילה לא בלילי רביעיות ולא בלילי שבתות מפני שאגרת בת מחלת היא ושמונה עשרה רבוא של מלאכי חבלה יוצאין וכל אחד ואחד יש לו רשות לחבל בפני עצמו","מעיקרא הוו שכיחי כולי יומא זמנא חדא פגעה ברבי חנינא בן דוסא אמרה ליה אי לאו דמכרזן עלך ברקיע הזהרו בחנינא ובתורתו סכנתיך אמר לה אי חשיבנא ברקיע גוזר אני עליך שלא תעבורי ביישוב לעולם אמרה ליה במטותא מינך שבק לי רווחא פורתא שבק לה לילי שבתות ולילי רביעיות","ותו חדא זמנא פגעה ביה באביי אמרה ליה אי לאו דמכרזי עלך ברקיע הזהרו בנחמני ובתורתו הוה סכנתיך א\"ל אי חשיבנא ברקיע גוזרני עלייכי שלא תעבורי ביישוב לעולם הא קא חזינן דעברה אמרי הני"],[[0,"שאין כל האצבעות שוות","אבר תשמיש שלא יהא תשמיש זה טוב לה כראשון ותזלזל בו:"],[1,"מצוה וגוף גדול","אם תרצה לעשות מצוה וגם תשתכר בה שיגדל ממונך:"],[1,"אוכל פירות ולא שכר","הלוה חבירך מעות על הקרקע לאכול פירות בנכייתא בזול שתנכה לו דבר מועט מן הדמים והיינו ריוח גדול וגם מצוה היא שיש ללוה שכר ריוח שצריך למעות ולסחורה:"],[3,"דלא תיגני בלא ק\"ש","שזה מנהג הארמאין:"],[4,"איכא דאמרי אל תשב במטה ארמית ממש משום מעשה דרב פפא","שהיתה ארמית אחת חייבת לו מעות ונכנס מדי יום יום בביתה לגבות הימנה יום אחד חנקה את בנה ונתנתו על המטה וכשנכנס רב פפא אמרה לו שב עד שאביא מעותיך וכן עשה כשבאתה אמרה המתה את בני וברח מן המדינה:"],[5,"וביומי ניסן","שהצמחים עולין וגס לבו בהן ונוגח:"],[7,"בדיקולא","בטרסקל שהוא אוכל בו:"],[7,"ניזהא דתורא","לחש על השור שלא ינגחנו:"],[8,"אמשכא דצלא","הישן על עור בבית העבדנין קודם שתגמר מלאכתו:"],[8,"חמימי דחמימי דשדא עילויה","אם רגיל לשפוך עליו מים חמים יותר מדאי על בשרו: מאן דמחוור לבושי' - ולביש להו מקמי ח' יומי דאכתי לא מטי ח' יומי דאשלחינהו הנהו כנים הדרי ואכתי איכא בהו חיותא ואכלי ליה וקשין לדבר אחר:"],[10,"בהדי תלתא","דהוה חד בעל דינך ותרי ליהוי סהדך:"],[11,"ובנדה דאורייתא","קודם שהחמירו על עצמן לישב ז' נקיים וטובלת ביום שפסק המעין אל תזקק באותו לילה הואיל והיום ראתה והוחזק מעין פתוח דילמא שפעה זיבה:"],[12,"שמא תפחת","ותחתיה חלל מלא מים:"]],[]],[["גזייתא נינהו דשמטי סוסיא ואתו דברי להו","(וא\"ל) רב לרב אסי לא תדור במתא דלא צניף בה סוסיא ולא נבח בה כלבא ואל תדור בעיר דריש מתא אסיא ולא תנסיב תרתי אי נסבת תרתי נסיב תלת","א\"ל רב לרב כהנא הפוך בנבילתא ולא תיפוך במילי פשוט נבילתא בשוקא ושקיל אגרא ולא תימא כהנא אנא וגברא רבא אנא וסניא בי מלתא סלקת לאיגרא שירותך בהדך מאה קרי במתא בזוזא תותי כנפיך ניהוו","א\"ל רב לחייא בריה לא תשתי סמא ולא תשוור ניגרא ולא תעקר ככא ולא תקנא בחיויא ולא תקנא בארמאה","תנו רבנן ג' אין מתקנאין בהן ואלו הן נכרי קטן ונחש קטן ותלמיד קטן מ\"ט דמלכותייהו אחורי אודנייהו קאי","א\"ל רב לאיבו בריה טרחי בך בשמעתא ולא מסתייע מילתא תא אגמרך מילי דעלמא אדחלא אכרעיך זבינך זבין כל מילי זבין ותחרט בר מחמרא דזבין ולא תחרט","שרי כיסיך פתח שקיך קבא מארעא ולא כורא מאיגרא","תמרא בחלוזך לבית סודנא רהיט ועד כמה אמר רבא עד תלתא סאה אמר רב פפא אי לא דרמאי שכרא לא איעתרי א\"ד אמר רב חסדא אי לא דרמאי שכרא לא איעתרי מאי סודנא אמר רב חסדא סוד נאה וגמילות חסדים","אמר רב פפא כל אגב גביא בעי כל אשראי ספק אתי ספק לא אתי ודאתי מעות רעות נינהו","ג' דברים א\"ר יוחנן משום אנשי ירושלים כשאתה יוצא למלחמה אל תצא בראשונה אלא תצא באחרונה כדי שתכנס בראשונה ועשה שבתך חול ואל תצטרך לבריות והוי משתדל עם מי שהשעה משחקת לו","(א\"ר) שלשה דברים א\"ר יהושע בן לוי משום אנשי ירושלים אל תרבה בגנות משום מעשה שהיה בתך בגרה שחרר עבדך ותן לה והוי זהיר באשתך מחתנה הראשון מ\"ט רב חסדא אמר משום ערוה רב כהנא אמר משום ממון הא והא איתנהו","אמר רבי יוחנן שלשה מנוחלי העוה\"ב אלו הן הדר בא\"י והמגדל בניו לתלמוד תורה והמבדיל על היין במוצאי שבתות מאי היא דמשייר מקידושא לאבדלתא","א\"ר יוחנן שלשה מכריז עליהן הקב\"ה בכל יום על רווק הדר בכרך ואינו חוטא ועל עני המחזיר אבידה לבעליה ועל עשיר המעשר פירותיו בצינעה רב ספרא רווק הדר בכרך הוה"],[[0,"גזייתא","כשמהלכים במבואות שבילי כרמים וסוסיהן משתמטין מכאן ובורחין ביישוב אתו ודברי להו:"],[0,"שראשה אסיא","רופא ואמרי לה ת\"ח ותרוייהו חד טעמא:"],[0,"סוסיא","משום דהוא נטירותא בקרתא מאויבים ומגנבים:"],[1,"ולא תינסב תרי","נשים שמא תתיעצנה עליך רעה:"],[1,"נסיב תלת","שאם תתיעצנה השלישית מגלה לך:"],[2,"פשוט נבילתא","הפשט עורה:"],[2,"סלקת לאיגרא שירותך בהדך","כשתצא לדרך אפי' קרובה צא ומזונותיך עמך:"],[2,"מאה קרי בזוזי תותי כנפיך להוו","אפילו המזונות בזול אעפ\"כ הוציאם עמך:"],[3,"לא תשתי סמא","לא תלמד לשתות סמים מפני שתקבע להון ווסת ויהא לבך שואלך ותפזר מעות. ל\"א לא תהא רגיל לשתות סממנים כדאמר (לעיל פסחים מב:): (כולהו שקייני) דמעלי להאי קשה להאי:"],[3,"לא תשוור ניגרא","פסיעה גסה שנוטלת מאור עינים:"],[3,"ולא תעקר ככא","שן ממש משום חולי:"],[4,"דמלכותייהו אחורי אודנייהו קיימי","כלומר עתידין לגדל ותגדל אימתן וינקמו ממך:"],[5,"אדחלא על כרעך זבינך זבין","בעוד שהחול על רגליך כשבאת מן הדרך מכור מה שהבאת כדי שתחזור ותקנה ותביא:"],[6,"שרי כיסך ופתח שקך","כלומר תקבל תחלה המעות ותנם בכיסך ואח\"כ פתח השק ותן התבואה ללוקחים:"],[6,"קבא מארעא ולא כורא מאיגרא","כלומר טוב לילך למקום קרוב ולהשתכר מעט מלהשתכר הרבה במדינת הים:"],[7,"תמרי בחלוזך לבי סודנא רהוט","אם יש לך תמרים באותו כלי שנותנים בו תמרים רוץ מיד לבית עושה שכר לעשות מהן שכר שאם תמתין תאכלם בין כך ובין כך ותפסיד:"],[7,"מאי סודנא","למה נקרא שם השכר סודנא:"],[7,"סוד נאה","עצה טובה שהרי מתעשרין הימנה:"],[7,"וגמילות חסדים","יכול לתת מתנה לעניים ולעשות צדקה וחסד:"],[8,"כל אגב גביא בעיא","כל דבר שצריך לכתוב שטר עליו כגון מלוה ואמנה בעייא גביא כלומר עדיין עומד הוא לגבות ויש לו טורח בו:"],[8,"מעות רעות","דפרע להו נהלייהו זוזא זוזא:"],[9,"צא באחרונה","שאם תנוס תכנס לביתך בראשונה:"],[10,"אל תרבה בגנות","כלומר אל תהא רגיל לעשות בית בפרהסיא במקום מגולה:"],[10,"משום מעשה שהיה","בדוד ובת שבע:"],[10,"משום ממון","שמבזבזת לו ממונך:"],[12,"רווק","פנוי:"]],[[2,"ולא תימא כהנא אנא","פירשתי באלו עוברין (לעיל פסחים דף מט:):"],[7,"אמר רב פפא אי לאו דרמאי שיכרא לא איעתרי","ובשילהי אלו עוברין (שם) קאמר רב פפא אי לאו דנסיבי כהנתא לא איעתרי י\"ל דהא והא גרמא ליה:"],[9,"עשה שבתך חול ואל תצטרך לבריות","והא דאמרינן בפ\"ב דביצה (דף טז:) דבהוצאת שבתות וימים טובים אם פוחת פוחתין לו היינו בשלו אם יש לו:"],[11,"דמשייר מקדושא לאבדלתא","שמונע שתייתו בשביל הבדלה ותימה דהא דוקא קידוש לילה קודם לכיבוד יום אבל הבדלה אינה קודמת ומפרש מורי הר\"י דקידוש יום קרי כיבוד יום והכי איתא בירושלמי פרק שלשה שאכלו רבי יוסי בשם רבי יעקב ב\"ר אדא איזהו כיבוד יום בפה\"ג:"]]],[["תני תנא קמיה דרבא ורב ספרא צהבו פניו דרב ספרא אמר לו רבא לאו כגון מר אלא כגון רב חנינא ורב אושעיא דהוו אושכפי בארעא דישראל והוו יתבי בשוקא דזונות ועבדי להו מסאני לזונות ועיילי להו אינהו מסתכלי בהו ואינהו לא מדלן עינייהו לאיסתכולי בהו ומומתייהו הכי בחייהן רבנן קדישי דבארעא דישראל:","שלשה הקדוש ברוך הוא אוהבן מי שאינו כועס ומי שאינו משתכר ומי שאינו מעמיד על מדותיו שלשה הקדוש ברוך הוא שונאן המדבר א' בפה ואחד בלב והיודע עדות בחבירו ואינו מעיד לו והרואה דבר ערוה בחבירו ומעיד בו יחידי","כי הא דטוביה חטא ואתא זיגוד לחודיה ואסהיד ביה קמיה דרב פפא נגדיה לזיגוד א\"ל טוביה חטא וזיגוד מינגד אמר ליה אין דכתיב (דברים יט, טו) לא יקום עד אחד באיש ואת לחודך אסהדת ביה שם רע בעלמא קא מפקת ביה","אמר רבי שמואל בר רב יצחק אמר רב מותר לשנאתו שנאמר (שמות כג, ה) כי תראה חמור שנאך רובץ תחת משאו מאי שונא אילימא שונא נכרי והא תניא שונא שאמרו שונא ישראל ולא שונא נכרי","אלא פשיטא שונא ישראל ומי שריא למסניה והכתיב (ויקרא יט, יז) לא תשנא את אחיך בלבבך אלא דאיכא סהדי דעביד איסורא כולי עלמא נמי מיסני סני ליה מאי שנא האי אלא לאו כי האי גוונא דחזיא ביה איהו דבר ערוה","רב נחמן בר יצחק אמר מצוה לשנאתו שנאמר (משלי ח, יג) יראת ה' (שונאי) רע אמר רב אחא בריה דרבא לרב אשי מהו למימרא ליה לרביה למשנייה אמר ליה אי ידע דמהימן לרביה כבי תרי לימא ליה ואי לא לא לימא ליה","תנו רבנן שלשה חייהן אינם חיים הרחמנין והרתחנין ואניני הדעת ואמר רב יוסף כולהו איתנהו בי","תנו רבנן שלשה שונאין זה את זה אלו הן הכלבים והתרנגולין והחברין וי\"א אף הזונות וי\"א אף תלמידי חכמים שבבבל","ת\"ר שלשה אוהבין זה את זה אלו הן הגרים ועבדים ועורבין","ארבעה אין הדעת סובלתן אלו הן דל גאה ועשיר מכחש וזקן מנאף ופרנס מתגאה על הציבור בחנם ויש אומרים אף המגרש את אשתו פעם ראשונה ושניה ומחזירה","ותנא קמא זימנא דכתובתה מרובה אי נמי יש לו בנים הימנה ולא מצי מגרש לה","חמשה דברים צוה כנען את בניו אהבו זה את זה ואהבו את הגזל ואהבו את הזמה ושנאו את אדוניכם ואל תדברו אמת","ששה דברים נאמרים בסוס אוהב את הזנות ואוהב את המלחמה ורוחו גסה ומואס את השינה ואוכל הרבה ומוציא קמעה וי\"א אף מבקש להרוג בעליו במלחמה","שבעה מנודין לשמים אלו הן יהודי שאין לו אשה ושיש לו אשה ואין לו בנים ומי שיש לו בנים ואין מגדלן לתלמוד תורה ומי שאין לו תפילין בראשו ותפילין בזרועו וציצית בבגדו ומזוזה בפתחו והמונע מנעלים מרגליו וי\"א אף מי שאין מיסב בחבורה של מצוה","אמר רבה בר בר חנה אמר רבי שמואל בר מרתא אמר רב משום רבי יוסי איש הוצל מניין שאין שואלין בכלדיים שנאמר (דברים יח, יג) תמים תהיה עם ה' אלהיך","ומניין היודע בחבירו שהוא גדול ממנו אפילו בדבר אחד שחייב לנהוג בו כבוד שנאמר (דניאל ו, ד) כל קבל די רוח יתירא ביה [ומלכא עשית להקמותיה על כל מלכותא]","והיושבת על דם טהור אסורה לשמש עד כמה אמר רב עונה","תנא הוא יוסף איש הוצל הוא יוסף הבבלי הוא איסי בן גור אריה הוא איסי בן יהודה הוא איסי בן גמליאל הוא איסי בן מהללאל ומה שמו איסי בן עקביה שמו הוא רבי יצחק בן טבלא הוא רבי יצחק בן חקלא הוא רבי יצחק בן אלעא הוא"],[[0,"תני תנא","להך מתניתא שלשה מכריז הקב\"ה עליהן לשבח בכל יום:"],[3,"מותר לשנוא אותו","הרואה דבר ערוה בחבירו יחידי אע\"פ שאינו רשאי להעיד מותר לשנאתו:"],[9,"אין הדעת סובלתן","אפילו הן עצמן מתחרטין לאחר זמן ונבזין הן בפני עצמן:"],[14,"בכלדיים","בעלי אוב:"],[16,"היושבת על דם","אף על פי שפסק המעין שלא ראתה:"],[16,"עונה","יום ולילה צריכין להמתין:"]],[[1,"שראה בו דבר ערוה","ואם תאמר דבאלו מציאות (ב\"מ דף לב: ושם) אמרינן אוהב לפרוק ושונא לטעון מצוה בשונא כדי לכוף את יצרו והשתא מה כפיית יצר שייך כיון דמצוה לשנאתו וי\"ל כיון שהוא שונאו גם חבירו שונא אותו דכתיב (משלי כ״ז:י״ט) כמים הפנים לפנים כן לב האדם לאדם ובאין מתוך כך לידי שנאה גמורה ושייך כפיית יצר:"],[6,"שלשה חייהן אינם חיים הרתחנין כו'","תימה דבפרק המביא (ביצה דף לב.) תניא ג' חייהן אינם חיים המצפה לשלחן חבירו ומי שאשתו מושלת עליו ומי שייסורין מושלין בגופו ואמאי לא מני לכולהו הכא ויש לומר דהכא לא מיירי אלא בהנך דהוו תולדת האדם משום דלעיל נמי איירי דדמי להנך שלשה הקב\"ה אוהבן מי שאינו כועס:"],[13,"ואין לו בנים","נראה דוקא על ידי פשיעתו שאינו מתעסק בפרי' ורביה דומיא דאחריני ומי שאין לו תפילין בראשו ובזרועו וציצית בבגדו מיירי בשיש לו ואינו מניחן אי נמי אפי' אין לו יש לחזר ולהביא עצמו לידי חיוב כדאשכחן (סוטה דף יד.) במשה שהיה תאב ליכנס לארץ ישראל כדי לקיים מצות שבה והא דאמרי' (שבת דף מט.) תפילין צריכין גוף נקי כאלישע היינו כדמפרש שלא יפיח בהן ולא יישן בהן ובשעת ק\"ש כדי לקבל עליו מלכות שמים שלימה בקל יכול ליזהר:"],[13,"ואין מיסב בסעודת מצוה","היינו סעודת מילה דאמר במדרש דניצול מדינה של גיהנם וסעודת נישואין בת\"ח ובת כהן לכהן ודוקא שיש שם בני אדם מהוגנין כדאמרינן בזה בורר (סנהדרין דף כג.) נקיי הדעת שבירושלים לא היו מסובין בסעודה אלא כן יודעין מי מיסב עמהם:"],[15,"צריך לנהוג בו כבוד","בשלא למד ממנו דבלמד ממנו אמרינן (אבות פ\"ו) בדוד (עשאו) [קראו רבו אלופו אע\"פ שלא למד אלא שני דברים מאחיתופל:"]]],[["רבי יצחק בן אחא דשמעתא הוא רבי יצחק בן פנחס דאגדתא וסימניך (שמעו נא אחיי ורעיי)","אמר רבה בר בר חנה א\"ר יוחנן משמיה דר' יהודה בר' אילעי אכול בצל ושב בצל ולא תיכול אווזין ותרנגולין ויהא לבך רודף עליך פחות ממיכלך וממשתיך ותוסיף על דירתך","כי אתא עולא אמר מתלא מתלין במערבא דאכיל אליתא טשי בעליתא דאכיל קקולי אקיקלי דמתא שכיב:","\u0001מתני׳\u0002 מזגו לו כוס ראשון ב\"ש אומרים מברך על היום ואחר כך מברך על היין וב\"ה אומרים מברך על היין ואחר כך מברך על היום:","\u0001גמ׳\u0002 ת\"ר דברים שבין ב\"ש וב\"ה בסעודה ב\"ש אומרים מברך על היום ואח\"כ מברך על היין מפני שהיום גורם ליין שיבא וכבר קידש היום ועדיין יין לא בא","וב\"ה אומרים מברך על היין ואח\"כ מברך על היום מפני שהיין גורם לקידוש שתאמר דבר אחר ברכת היין תדירה וברכת היום אינה תדירה תדיר ושאינו תדיר תדיר קודם והילכתא כדברי ב\"ה","מאי ד\"א וכ\"ת התם תרתי והכא חדא הכא נמי תרתי נינהו תדיר ושאינו תדיר תדיר קודם","והלכה כדברי ב\"ה פשיטא דהא נפיק בת קול איבעית אימא קודם בת קול","ואי בעית אימא לאחר בת קול ורבי יהושע היא דאמר אין משגיחין בבת קול:","\u0001מתני׳\u0002 הביאו לפניו מטבל בחזרת עד שמגיע לפרפרת הפת הביאו לפניו מצה וחזרת וחרוסת ושני תבשילין אע\"פ שאין חרוסת מצוה ר\"א (בן) צדוק אומר מצוה ובמקדש היו מביאין לפניו גופו של פסח: \u0001גמ׳\u0002"],[[0,"רבי יצחק ב\"ר אחא דשמעתא","רבי יצחק סתם האמור באגדתא ר' יצחק בן פנחס הוא:"],[0,"שמעו נא אחיי","דשמעתא בן אחא:"],[1,"ולבך רודף עליך","מתאוה לאכול כל שעה שהורגלת:"],[2,"קקולי","ירקות:"],[2,"אקיקלי דמתא","על אשפות העיר מקום ששאר בני העיר יושבין הואיל ואין תובעין לו כלום:"],[3,"מתני' מברך על היין","וה\"ה למקדש על הפת:"],[5,"גמ' שהיין גורם לקידוש שתיאמר","שאם אין לו יין או פת אינו מקדש:"],[9,"מתני' הביאו לפניו","ירקות:"],[9,"מטבל בחזרת","זהו לשון הגמרא כדתניא לעיל (פסחים דף קז:) השמש מטבל בבני מעים לפי שכל מאכלם ע\"י טיבול:"],[9,"מטבל בחזרת","כלומר אם אין שם ירק אחר מטבל החזרת בחרוסת ואוכל:"],[9,"עד שמגיע לפרפרת הפת","קודם שיגיע לאותה חזרת שהוא אוכל אחר המצה שהוא מברך עליה על אכילת מרור וטיבול ראשון כדי שיכיר תינוק וישאל לפי שאין רגילין בני אדם לאכול ירק קודם סעודה:"],[9,"הביאו לפניו","אחר אותו טיבול:"],[9,"מצה מרור וחרוסת ושני תבשילין ואף על פי שאין החרוסת מצוה","ולקמיה פריך הואיל ולאו מצוה אמאי מייתי לה:"]],[[8,"דאמר אין משגיחים בבת קול","וא\"ת מאי שנא דקי\"ל כבת קול דב\"ה ולא קי\"ל כב\"ק דרבי אליעזר וי\"ל דהכא ב\"ה הוו רובא אלא דב\"ש מחדדי טפי אבל התם דב\"ק היה כנגד רבים לא קי\"ל הכי ובת קול לא יצתה אלא לכבודו כדקאמרינן התם מן השמים יוכיחו וא\"ת א\"כ היכי קאמר רבי יהושע היא הא רבי יהושע קאי אבת קול דר\"א וי\"ל מדקאמר אין משגיחין בב\"ק משום דלא (מן השמים) היא משמע דבכל דוכתא לית לן למיזל בתר בת קול:"],[9,"הביאו לפניו","פי' רשב\"ם ירקות. ואין נראה מדלא קתני בהדיא הביאו לפניו חזרת כדקתני בסמוך הביאו לפניו מצה ונראה כפי' ר\"ח הביאו לפניו שלחן שהרי אין מביאין השלחן עד אחר קידוש ועל השלחן מונח החזרת:"],[9,"מטבל בחזרת","כלומר אוכל החזרת בטיבול כמו השמש מטבל בבני מעים וכן מטבל בירקות ובקרא נמי משתעי הכי כי תקרעי בפוך עיניך (ירמיהו ד) שמנחת הפוך בעינים ופי' רשב\"ם דהאי טיבול לאו בחרוסת דהא אכתי לא בא כדקתני סיפא הביאו לפניו מצה וחזרת וחרוסת ואין זה ראיה דהא קתני הכא חזרת ותניא נמי בסיפא ועוד דחזרת צריך להטביל בחרוסת משום קפא ומיהו היכא שהטיבול ראשון הוי בשאר ירקות אין צריך לטבול בחרוסת אלא או בחומץ או במים ומלח כמו שהיה נוהג ר\"ת דהא אמר בגמרא דחרוסת משום קפא וליכא קפא אלא במרור וכ\"ש לר\"א בר צדוק דקאמר מצוה זכר לטיט דלא שייך אלא במרור לזכר דוימררו את חייהם בחומר (שמות א) ועוד דלא שייך מצוה שטיבול ראשון אינו אלא להיכירא ודלא כה\"ר יוסף שעשה בסדרו ויטבול בחרוסת וכן רבינו שלמה בסידרו וה\"ר שמעיה:"],[9,"עד שמגיע לפרפרת הפת","פרפרת קרי המרור שאוכל אחר המצה ופרפרת כלומר ממשכת המאכל כמו פרפראות לחכמה (אבות פ\"ג מי\"ח) שהירקות ממשיכות הלב למאכל ומדקרי למרור פרפרת הפת רמז במשנה דמצה קודמת למרור כדאמר בגמרא:"],[9,"הביאו לפניו מצה","לפי שעקרו השלחן לפני מי שאומר הגדה ועושה הסדר קתני הביאו לפניו מצה ועקירת שלחן היא כדי שישאל הבן ואביו עונה לו עדיין יביאו שלחן לעשות טיבול שני והבן ישאל למה אנו מטבילין שתי פעמים ומיד כשעוקרין מחזירין לפניו והמצה והמרור עליו שהרי צריך לומר בהגדה מצה זו מרור זה וכדאמר (לעיל פסחים לו. ולקמן פסחים דף קטו:) לחם עוני שעונין עליו דברים הרבה:"],[9,"אע\"פ שאין חרוסת מצוה","ואם תאמר אמאי לא אתי חרוסת דרשות ומבטל חזרת דמצוה וי\"ל דכיון דכל עיקר מרור לא ניתקן רק בטיבול בחרוסת משום קפא לא מקרי ביטול בכך:"]]],[["אמר ר\"ל זאת אומרת מצות צריכות כוונה כיון דלא בעידן חיובא דמרור הוא דאכיל ליה בבורא פה\"א הוא דאכיל ליה ודילמא לא איכוון למרור הלכך בעי למהדר לאטבולי לשם מרור דאי סלקא דעתך מצוה לא בעיא כוונה למה לך תרי טיבולי והא טביל ליה חדא זימנא","ממאי דילמא לעולם מצות אין צריכות כוונה ודקאמרת תרי טיבולי למה לי כי היכי דליהוי היכירא לתינוקות","וכי תימא א\"כ לישמעינן שאר ירקות אי אשמעינן שאר ירקות הוה אמינא היכא דאיכא שאר ירקות הוא דבעינן תרי טיבולי אבל חזרת לחודא לא בעי תרי טיבולי קמשמע לן דאפי' חזרת בעינן תרי טיבולי כי היכי דליהוי ביה היכירא לתינוקות","ועוד תניא אכלן דמאי יצא אכלן בלא מתכוין יצא אכלן לחצאין יצא","ובלבד שלא ישהא בין אכילה לחבירתה יותר מכדי אכילת פרס","תנאי היא דתניא רבי יוסי אומר אע\"פ שטיבל בחזרת מצוה להביא לפניו חזרת וחרוסת ושני תבשילין","ואכתי ממאי דילמא קסבר רבי יוסי מצות אין צריכות כוונה והאי דבעינן תרי טיבולי כי היכי דתיהוי היכירא לתינוקות א\"כ מאי מצוה","מאי שני תבשילין אמר רב הונא סילקא וארוזא רבא הוה מיהדר אסילקא וארוזא הואיל ונפיק מפומיה דרב הונא","אמר רב אשי שמע מינה דרב הונא לית דחייש להא דרבי יוחנן בן נורי דתניא רבי יוחנן בן נורי אומר אורז מין דגן הוא וחייבין על חימוצו כרת ואדם יוצא בו ידי חובתו בפסח","חזקיה אמר אפי' דג וביצה שעליו רב יוסף אמר צריך שני מיני בשר אחד זכר לפסח וא' זכר לחגיגה רבינא אמר אפילו גרמא ובישולא","פשיטא היכא דאיכא שאר ירקות מברך אשאר ירקות בורא פרי האדמה ואכיל והדר מברך על אכילת מרור ואכיל","היכא דליכא אלא חסא מאי אמר רב הונא מברך מעיקרא אמרור ב\"פ האדמה ואכיל ולבסוף מברך עליה על אכילת מרור ואכיל"],[[0,"גמ' זאת אומרת מצות צריכות כונה","משום הכי בעי תרי טיבולי שמא לא נתכוון לשם מרור הואיל ובירך בורא פרי האדמה כשאר ירקות דעלמא:"],[2,"דילמא הא קמשמע לן דבעינן תרי טיבולי","משום תינוקות שישאלו ועבדינן היכירא טובא:"],[3,"אכלו לחצאין","חצי זית בפעם ראשונה וחצי זית בפעם שניה ובמרור קא איירי:"],[5,"תנאי היא","דהאי תנא לית ליה צריכות כוונה ור' יוסי אית ליה צריכות כוונה:"],[8,"ש\"מ","מדקאמר רב הונא דמבשלין אורז בפסח ולא חייש לחימוץ לית דחש לה לדרבי יוחנן:"],[9,"אפילו דג וביצה שעליו","שהיו רגילין להטיח את הדג בביצים:"],[9,"ואחד זכר","לחגיגת ארבעה עשר:"],[9,"גרמא ובישולא","חתיכת בשר ומן המרק:"],[10,"פשיטא היכא דאיכא שאר ירקי","מברך מעיקרא אירקי בורא פרי האדמה דאסור ליהנות מן העולם בלא ברכה וכיון דיש לו שאר ירקות הכי שפיר טפי שיברך בפה\"א על הירקות תחלה דהיינו ברכה הראויה להם ויפטור את המרור הבא אחריו מברכת בפה\"א ואח\"כ יברך על החזרת על אכילת מרור:"]],[[0,"זאת אומרת מצות צריכות כוונה","ריש לקיש סבר דמתני' סתמא קתני ומיירי אפי' יכול למצוא שאר ירקות אין לו לטרוח אחר שאר ירקות אלא עושה שני טיבולין במרור והיינו משום דמצות צריכות כוונה וכיון דלא בעידן כו' ובבורא פרי האדמה הוא דאכיל ליה כלומר שלא בירך על אכילת מרור ודילמא לא איכוון ודילמא לאו דוקא כלומר ודאי לא איכוון למרור דאין מצוה אלא עד טיבול שני אחר מצה הלכך בעי למהדר ואטבולי פי' ולברך על אכילת מרור ולא נקט וברוכי משום דרב חסדא אית ליה בשמעתין דמברך על אכילת מרור בטיבול ראשון והא דקאמר ובבורא פרי האדמה אכיל ליה היינו כלומר שאינו אוכל לשם אכילת מרור אלא אכלו לצאת בבורא פרי האדמה דאי סלקא דעתך לא בעי כוונה אם כן יצא חובת מרור בטיבול ראשון אע\"ג דאכלו לפני מצה וכתיב על מצות ומרורים לא הויא עיכובא אמאי צריך תרי טיבולי במרור הוה ליה לאהדורי אשאר ירקות משום היכירא בטיבול ראשון ואחר מצה בטיבול שני יאכל מרור והגמרא דחי דלעולם אין צריכות כוונה ומהדרינן אשאר ירקי משום היכירא וכדי לאכול מרור אחר המצה ומתניתין קמ\"ל היכא דליכא שאר ירקי דאפי' במרור בעינן תרי טיבולי כדי לאכול מרור כמצוותו ומשום היכירא ולא אמרי' שלא יאכל מרור עד לבסוף ולא נחוש להיכירא:"],[3,"אכלן דמאי יצא","אבל ודאי לא יצא אע\"ג דמעשר ירק דרבנן כדאמרינן גבי מצה בכל שעה (לעיל פסחים דף לה:) אבל לא בטבל ומוקי לה בטבל טבול מדרבנן ואיתקש מרור למצה ובדמאי יצא נמי במצה משום דאי בעי מפקיר נכסיה וחזי ליה וטעמא דהחמירו בודאי דרבנן דטבל דאורייתא מפיק התם (לעיל פסחים דף לה:) מלא תאכל עליו חמץ יצא זה שאיסורו משום בל תאכל טבל ואיתקש מצה לחמץ:"],[3,"אכלו בלא מתכוין יצא","קשיא לריש לקיש ואע\"ג דריש לקיש דייק ממתניתין ע\"כ מתניתין לא איירי בכל ענין אלא בדליכא שאר ירקות וקא משני תנאי היא וכיון דאיכא תנא דסבר כריש לקיש דייק שפיר ריש לקיש ממתניתין דצריכות כוונה כי מסתמא איירי בכל ענין אפי' איכא שאר ירקות:"],[7,"סילקא וארוזא","וכ\"ש שני מיני בשר:"],[8,"לית דחש לה לדר' יוחנן בן נורי","וטעמא דאינו בא לידי חימוץ אלא לידי סרחון בפ' כל שעה (לעיל פסחים דף לה.):"],[9,"שני מיני בשר","פירוש ר\"ח צלי זכר לפסח ומבושל זכר לחגיגה ולא נהירא דקיימא לן כבן תימא (לעיל פסחים דף ע.) דאין חגיגה נאכלת אלא צלי דמתניתין אתיא כוותיה לכך נראה דתרוייהו מבושלין וכן משמע לשון תבשילין:"],[9,"אחד זכר לפסח ואחד לחגיגה","כשחל י\"ד להיות בשבת אין צריך רק בישול אחד דחגיגת י\"ד אינה דוחה את השבת ומיהו אומר ר\"י דמ\"מ אין לחלק דדמי לחובה אם היינו מניחים מלעשות שני תבשילין וגם יש לחוש שמא לא יעשו בשאר פסחים ואין שום חשש אם אנו עושין אע\"ג דלא צריך דליכא למיחש שמא יבנה בית המקדש ויאמרו אשתקד עשינו זכר לחגיגה בשבת והשתא נמי נקריבה בשבת דהקרבה מסורה לזריזין וכשיבנה משה ואהרן יהא עמנו וליכא למיטעי אך הבא להניח מלעשות שני תבשילין אין מזהירין אותו:"],[11,"אמר רב הונא מברך כו'","רב הונא סבר כריש לקיש דבעי כוונה ואפי' אית ליה שאר ירקות עביד במרור שני טיבולי:"]]],[["מתקיף לה רב חסדא לאחר שמילא כריסו הימנו חוזר ומברך עליה אלא אמר רב חסדא מעיקרא מברך עליה בורא פרי האדמה ועל אכילת מרור ואכיל ולבסוף אכיל אכילת חסא בלא ברכה","בסוריא עבדי כרב הונא ורב ששת בריה דרב יהושע עביד כרב חסדא והלכתא כוותיה דרב חסדא רב אחא בריה דרבא מהדר אשאר ירקות לאפוקי נפשיה מפלוגתא","אמר רבינא אמר לי רב משרשיא בריה דרב נתן הכי אמר הלל משמיה דגמרא לא ניכרוך איניש מצה ומרור בהדי הדדי וניכול משום דסבירא לן מצה בזמן הזה דאורייתא ומרור דרבנן ואתי מרור דרבנן ומבטיל ליה למצה דאורייתא","ואפילו למ\"ד מצות אין מבטלות זו את זו ה\"מ דאורייתא בדאורייתא או דרבנן בדרבנן אבל דאורייתא ודרבנן אתי דרבנן ומבטיל ליה לדאוריית'","מאן תנא דשמעת לי' מצות אין מבטלות זו את זו הלל היא דתניא אמרו עליו על הלל שהיה כורכן בבת אחת ואוכלן שנאמר (במדבר ט, יא) על מצות ומרורים יאכלוהו","אמר רבי יוחנן חולקין עליו חביריו על הלל דתניא יכול יהא כורכן בבת אחת ואוכלן כדרך שהלל אוכלן תלמוד לומר על מצות ומרורים יאכלוהו אפילו זה בפני עצמו וזה בפני עצמו מתקיף לה רב אשי אי הכי מאי אפילו","אלא אמר רב אשי האי תנא הכי קתני יכול לא יצא בהו ידי חובתו אא\"כ כורכן בבת אחת ואוכלן כדרך שהלל אוכלן תלמוד לומר על מצות ומרורים יאכלוהו אפילו זה בפני עצמו וזה בפני עצמו","השתא דלא איתמר הלכתא לא כהלל ולא כרבנן מברך על אכילת מצה ואכיל והדר מברך על אכילת מרור ואכיל והדר אכיל מצה וחסא בהדי הדדי בלא ברכה זכר למקדש כהלל","אמר רבי אלעזר אמר רב אושעיא כל שטיבולו במשקה צריך נטילת ידים אמר רב פפא שמע מינה האי חסא"],[[0,"ולבסוף אכיל","בלא ברכה משום דבעינן תרי טבולין:"],[2,"ומבטל ליה","לטעם מצה דאורייתא:"],[4,"שהיה כורכן בבת אחת","פסח מצה ומרור:"],[7,"זכר למקדש כהלל","זכר למה שהיה עושה הלל בזמן שבהמ\"ק קיים שהיו אוכלים פסחיהם:"],[8,"צריך נטילת ידים","משום המשקין שהידים שניות וכל הפוסל בתרומה מטמא משקין וכו':"]],[[0,"מתקיף לה רב חסדא לאחר שמילא כריסו כו'","רב חסדא נמי נראה דסבר כר\"ל דבעי כוונה אעפ\"כ סבר דאין נכון לברך בטיבול שני כיון שכבר מילא כריסו דאי סבר אין צריכות כוונה ה\"ל למימר בהדיא דנפיק בטיבול ראשון ואם יברך בטיבול שני הויא ברכה לבטלה ולא צריך לרב חסדא לאהדורי אשאר ירקי ומברך לרב חסדא בטיבול ראשון על אכילת מרור אע\"ג דעיקר מצות מרור לא נפיק אלא בטיבול שני אחר מצה מועלת הברכה שבירך בטיבול ראשון לטיבול שני מאחר שאכל ממנו מעט בטיבול ראשון מידי דהוה אברכת שופר דמברך אתקיעות דישיבה ומועלת ברכה לתקיעות שבעמידה שהם עיקר ונעשית על סדר ברכות והשתא כל אלו אמוראי סברי דבעי כוונה וסתמא דמסדר הש\"ס סבר הכי מדאיצטריך לפסוק כרב חסדא ואי אין צריכות כוונה פשיטא דלא יברך בטיבול שני דאפילו לא בירך בטיבול ראשון נפק ביה ואי יברך בטיבול שני הויא ברכה לבטלה ולית הלכתא כוותיה דאבוה דשמואל דאית ליה בפרק ראוהו ב\"ד (ר\"ה דף כח.) אין צריכות כוונה דקאמר בכפאו ואכל מצה יצא ומוקי לה בכפאוהו פרסיים והתם לא מייתי מאכלו בלא מתכוין משום דלגבי אכילה לא בעינן כוונה כולי האי כמו בתפלה ותקיעה ומש\"ה נמי לא מייתי הכא ברייתות דהתם דבעו כוונה דגבי תפלה ותקיעה בעי כוונה טפי כדפרישית:"],[0,"והדר אכיל חסא בלא ברכה","ונראה דאין צריך לברך בפה\"א אע\"ג דהגדה הוי הפסק כדפרישית לעיל ולא מיפטר בברכה של טיבול ראשון מ\"מ ברכת המוציא פוטרתן דהוה להו דברים הבאים בתוך הסעודה מחמת הסעודה שהרי ירקות גוררין הלב וקרי ליה נמי למרור פרפרת הפת וכן אמר בכיצד מברכין (ברכות ד' מב.) בירך על הפת פטר את הפרפרת פרפר' היינו דברים הממשיכים האכילה כגון דגים קטנים ותמרים וירקות והיו רגילים לאוכלם בתוך הסעודה בין מאכל למאכל ולכך פטר את הפרפרת לפי שבא לצורך שעל ידי כך אוכל יותר ואין לומר דפרפרת היינו דבר שבא ללפת בו את הפת דהא הוי בכלל הא דקתני התם דמברך על העיקר ופוטר את הטפילה וקאמר נמי רבי חייא פת פוטרת כל מיני מאכל ורב פפא נמי פסיק התם הלכתא דברים הבאים תוך הסעודה מחמת הסעודה והיינו הפרפרת כדפי' אין טעונין ברכה לא לפניהם ולא לאחריהם שלא מחמת הסעודה תוך הסעודה כגון תאנים וענבים שאינן באין להמשיך המאכל ולא ללפת אלא לתענוג צריכין ברכה לפניהם ולא לאחריהם אחר הסעודה אפילו פרפרת טעונין ברכה בין לפניהם בין לאחריהם וה\"ר יוסף טוב עלם כתב בסדרו למה שאר ירקות באין תחלה לפטור חזרת מברכה ראויה לה וליתא דהא משום היכירא באין ולא שייך כאן חבילות אלא בתרי מילי ועוד דרב חסדא מברך שתיהן אחזרת ועוד דמשמע דלא פטר ליה פת ושמא אינו מחשיבו פרפרת הפת כיון שאינו אוכל ממנו אלא כזית:"],[2,"אתי מרור דרבנן ומבטל למצה דאורייתא","וכל שכן דאי לא הוי מרור אפי' מדרבנן דמבטל להמצה כדמשמע לקמן והא דשרי בהקומץ (מנחות דף כג:) מצה מתובלת לא אתו בשמים ומבטלו למצה דאין מן הבשמים כי אם דבר מועט ודלא כאותן שאסרו מצה מתובלת בשם רש\"י אף בימים אחרונים משום דמחמעי לה:"],[6,"אלא אמר רב אשי","אין נראה כפירוש הקונטרס דמשבש רב אשי מילתיה דרבי יוחנן שהרי טוב להגיה הברייתא אפילו לחסר כמו שאנו מגיהין כמה ברייתות מלשבש דברי ר' יוחנן אלא רב אשי מתקיף אבני ישיבה דמפרשי דחולקין רבנן ואסרי לכרוך דא\"כ מאי אפילו אלא רבנן סברי דבכל ענין מצותן בין ע\"י כריכה בין כל אחד לבדו ופליגי אהלל דמצריך לכרוך ונקטי רבנן אפילו משום הלל וא\"ת מנא לן דסבר הלל דאין מבטלות דילמא שאני הכא דגלי קרא ועוד הא לרבנן נמי אין מבטלות דהא אם כרכן נמי יצא וי\"ל מדסבר דלכתחלה יש לו לכרוך ובדיעבד נפיק כי לא כריך אם כן בעלמא אין מבטלות דאי מבטלות א\"כ איצטריך קרא הכא להתיר כריכה ולומר דהכא לא מבטלי והלכך לרבנן דמוקי קרא בדיעבד שמעינן דבעלמא מבטלות ושאני הכא דגלי קרא:"],[7,"אלא מברך אמצה ואכיל ומברך אמרור כו'","אם היה כורך שניהם יחד תחלה הוה אתי מרור דרבנן ומבטל למצה ואם היה אוכל מצה בלא מרור תחלה כשהיה כורכן אחר כך אתי מצה דרשות ומבטל מרור דרבנן ומיהו אי הוה קיימא לן כהלל הוה עבדינן הכי מצה לחודא והדר מצה ומרור בכריכה כיון שצריך לעשות מדרבנן מצות כריכה כהלל הוה דרבנן ודרבנן:"],[8,"כל שטיבולו במשקה צריך נטילה","פי' בקונ' אע\"ג דקי\"ל (חולין דף קו.) הנוטל ידיו לפירות ה\"ז מגסי הרוח כיון דאיכא משקין וקיי\"ל (פרה פ\"ח משנה ז) כל הפוסל את התרומה מטמא משקין להיות תחלה הוה להו הנך פירות כמו נהמא וצריך ליטול כמו בנהמא ואין נראה לפרש כן דאם כן כי פריך למה לי נטילת ידים הא לא נגע ומאי נפקא מיניה אפילו אי לא נגע כיון דסוף סוף אכיל משקה המטובל לא גרע מאוכל מחמת מאכיל דבעי נטילת ידים ועוד וכי לא ידע המקשה דאיכא למיחש דילמא נגע כדאמר רב פפא ונראה דנטילה דהכא לא משום קדושה ונקיות כמו בנהמא אלא משום שלא יטמא המשקין להיות תחלה ויהא אסור לשתותן ולפסול את גופו כדתנן בפ\"ב דחולין (דף לג.) השוחט ולא יצא מהן דם כו' הא יצא מהן דם אין נאכלין בידים מסואבות ואמר נמי בסדר הסיבה (ברכות דף מג.) הביאו להן יין כל אחד נוטל ידו אחת פי' שלא יטמא היין ויפסול גופו והתם סגי ביד אחת אבל במרור נוגע בב' ידיו וקאמר הסיבו מביאין להם מים אע\"פ שכל אחד כבר נטל ידו אחת חוזר ונוטל ב' ידיו אע\"ג דאמרינן (ידים פ\"ב מ\"א) נטל ידו אחת משטיפה אחת טהורה צריך ליטול שתיהן ולפי שנטילה ראשונה לא היתה לשם קדושה לכך סבר המקשה דבהך נטילה ליכא למיגזר שמא יגע ולפי זה נראה דאין לברך על אותה נטילה כיון דליכא הכא מצוה לשמוע דברי ר\"א בן ערך (חולין דף קו.) וכ\"ש אנן שאין אנו נזהרין מלטמאות עצמנו ומלאכול אוכלין טמאין ואין אנו צריכין לאותה נטילה והמברך הרי זה מברך ברכה לבטלה ובכל סדרים כתיב שצריך על הנטילה לברך ואין נראה כדפרישית:"]]],[["צריך לשקועיה בחרוסת משום קפא דאי ס\"ד לא צריך לשקועיה נטילת ידים למה לי הא לא נגע ודילמא לעולם אימא לך לא צריך לשקועיה וקפא מריחא מיית אלא למה לי נטילת ידים דילמא משקעו ליה","ואמר רב פפא לא נישהי איניש מרור בחרוסת דילמא אגב חלייה דתבלין מבטיל ליה למרוריה ובעינן טעם מרור וליכא אדבריה רב חסדא לרבנא עוקבא ודרש נטל ידיו בטיבול ראשון נוטל ידיו בטיבול שני","אמרוה רבנן קמיה דרב פפא הא בעלמא איתמר דאי סלקא דעתך הכא איתמר למה לי נטילת ידים תרי זימני הא משא ליה ידיה חדא זימנא","אמר להו רב פפא אדרבה הכא איתמר דאי ס\"ד בעלמא איתמר למה לי תרי טיבולי","אלא מאי הכא איתמר נטילת ידים תרי זימני למה לי הא משא ליה ידיה חדא זימנא אמרי כיון דבעי למימר אגדתא והלילא דילמא אסוחי אסחיה לדעתיה ונגע","אמר רבא בלע מצה יצא בלע מרור לא יצא בלע מצה ומרור ידי מצה יצא ידי מרור לא יצא כרכן בסיב ובלען אף ידי מצה נמי לא יצא","אמר רב שימי בר אשי מצה לפני כל אחד ואחד מרור לפני כל אחד ואחד וחרוסת לפני כל אחד ואחד ואין עוקרין את השלחן אלא לפני מי שאומר הגדה","רב הונא אומר כולהו נמי לפני מי שאומר הגדה והלכתא כרב הונא","למה עוקרין את השולחן אמרי דבי ר' ינאי כדי שיכירו תינוקות וישאלו אביי הוה יתיב קמיה דרבה חזא דקא מדלי תכא מקמיה אמר להו עדיין לא קא אכלינן אתו קא מעקרי תכא מיקמן אמר ליה רבה פטרתן מלומר מה נשתנה:","אמר שמואל (דברים טז, ג) לחם עוני (כתיב) לחם שעונין עליו דברים תניא נמי הכי לחם עוני לחם שעונין עליו דברים הרבה דבר אחר לחם עוני עני כתיב מה עני שדרכו בפרוסה"],[[0,"צריך לשקועיה בחרוסת משום קפא","ארס שבחזרת שהשרף שבחזרת יש בו ארס כדרך הבצלים:"],[0,"הא לא נגע","ידו במשקה:"],[2,"הא בעלמא איתמר","בשאר טיבולין שאינן קבע צריך שיטול ידיו לטיבול דכשנטל ידיו לראשון לא היה יודע שסוף שני לבוא:"],[2,"דאי ס\"ד הכא","גבי מרור איתמר אמאי הא משי ליה חדא זמנא בטיבול ראשון:"],[4,"אסחיה לדעתיה ונגע","בבשרו:"],[5,"בלע מצה","ולא לעסה יצא:"],[5,"בלע מרור (לא) יצא","אפשר שלא טעם בו טעם מרור:"],[5,"בלע מצה ומרור","יחד ולא אכל עדיין לא מזה ולא מזה יצא ידי מצה שאינה צריכה טעם אבל ידי מרור לא יצא הואיל ולא לעסו ואוכל מצה עמו אין לו שום טעם:"],[5,"כרכן","שניהם יחד בסיב הדקל לא יצא שהרי לא היה ממש בפיו לא זה ולא זה:"],[6,"ואין עוקרין את השלחן","א\"צ להגביה קערה כשמתחיל הגדה אלא מלפני הגדול שבהן שעושה הסדר ואומר ההגדה:"]],[[0,"קפא","פי' ר\"ח תולעת כדתניא התולעת שבעיקרי זיתים ושבעיקרי גפנים והקפא שבירק והיבחושין שביין וחומץ הרי אלו מותרים וא\"ת תיקשי מינה לשמואל דאמר בסוף אלו טריפות (חולין דף סז.) קישות שהתליע באיביה אסור משום שרץ השורץ על הארץ ומיהו שמואל סבר כאידך ברייתא דמייתי התם ומיהו ק\"ק דמ\"מ אמאי לא מייתי הך ברייתא התם ועוד שמואל היכי אכיל מרור בפסח וכי תימא דבדיק להו שלא יהא שם קפא א\"כ אמאי צריך חרוסת כיון דליכא קפא ושמא ברוב ירקות אין בהם קפא וסמיך שמואל ארובא ומשום סכנה דקפא חיישינן למיעוטא וצריך חרוסת:"],[1,"צריך שיטול בטיבול שני","לאו דוקא נקט בטיבול שני דהא עביד ליה בתר המוציא דבעי נטילת ידים אלא אגב טיבול ראשון נקט טיבול שני והנטילה נמי גם לצורך טיבול באה:"],[4,"אסוחי מסח דעתיה ונגע","תימה מה צריך להאי טעמא תיפוק ליה דנטילה ראשונה לא היתה לשם קדושה אלא שלא יטמא את המשקין וי\"ל דס\"ד דכיון שנטל יועיל אפילו לנהמא דחולין לא בעי כוונה לכך צריך להאי טעמא:"],[5,"ידי מצה יצא ידי מרור לא יצא","וא\"ת כיון שאין במרור זה מצוה מדרבנן ליבטיל מרור להאי מצה דבהדיה וי\"ל דלא שייך ביטול אלא כשלועסן יחד דאז מבטל טעם אחד את חבירו אבל כשהם שלמים אפילו יהיה יותר מחבירו לא מבטל ליה:"],[6,"מצה לפני כל אחד ואחד מרור כו'","נראה דטעמא כדי שיטעום תיכף לברכה מיד כיון שזאת הברכה היא לשם חובה אבל בשאר ימות השנה דאין הברכה חובה אין צריך לטעום תיכף לברכה מיד:"],[8,"למה עוקרין את השלחן","דוקא שלהן שהן קטנים אבל שלנו שהן גדולים איכא טורח גדול בעקירתו נהגו לסלק הקערה לצד אחד דליהוי כעקירת שלחן ומה שנוהגין לסלק שני תבשילין בשעת הגבהה כדי שלא יהא נראה כמקדיש קדשים בחוץ וכן יסד ה\"ר יוסף בסדרו מושך מהקערה שני תבשילין ומגביה קערה ולימא הא לחמא עניא כו' ולא יתכן דהא דאמר בשר אינו צריך להגביה היינו בשעה שאומר פסח זה דאז ודאי נראה כאוכל קדשים:"],[8,"כדי שיכיר התינוק וישאל","כלומר ומתוך כך יבא לישאל בשאר דברים אבל במה ששאל למה אנו עוקרין השלחן לא יפטר ממה נשתנה וההיא דאביי לא פי' הגמ' אלא תחלת שאילתו:"]]],[["אף כאן בפרוסה דבר אחר מה דרכו של עני הוא מסיק ואשתו אופה אף כאן נמי הוא מסיק ואשתו אופה","אע\"פ שאין חרוסת מצוה: ואי לא מצוה משום מאי מייתי לה א\"ר אמי משום קפא אמר רב אסי קפא דחסא חמא קפא דחמא כרתי [קפא דכרתי חמימי] קפא דכולהו חמימי אדהכי והכי נימא הכי קפא קפא דכירנא לך ולשב בנתיך ולתמני כלתך:","רבי אלעזר בר' צדוק אומר מצוה וכו': מאי מצוה רבי לוי אומר זכר לתפוח ור' יוחנן אומר זכר לטיט אמר אביי הלכך צריך לקהוייה וצריך לסמוכיה לקהוייה זכר לתפוח וצריך לסמוכיה זכר לטיט","תניא כוותיה דרבי יוחנן תבלין זכר לתבן חרוסת זכר לטיט אמר רבי אלעזר בר' צדוק כך היו אומרים תגרי חרך שבירושלים בואו וטלו לכם תבלין למצוה:","\u0001מתני׳\u0002 מזגו לו כוס שני וכאן הבן שואל אביו ואם אין דעת בבן אביו מלמדו","מה נשתנה הלילה הזה מכל הלילות שבכל הלילות אנו אוכלין חמץ ומצה הלילה הזה כולו מצה שבכל הלילות אנו אוכלין שאר ירקות הלילה הזה מרור שבכל הלילות אנו אוכלין בשר צלי שלוק ומבושל הלילה הזה כולו צלי שבכל הלילות (אין) אנו (חייבים לטבל אפילו) פעם אחת הלילה הזה שתי פעמים","ולפי דעתו של בן אביו מלמדו מתחיל בגנות ומסיים בשבח ודורש (דברים כו, ה) מארמי אובד אבי עד שיגמור כל הפרשה כולה:","\u0001גמ׳\u0002 ת\"ר חכם בנו שואלו ואם אינו חכם אשתו שואלתו ואם לאו הוא שואל לעצמו ואפילו שני תלמידי חכמים שיודעין בהלכות הפסח שואלין זה לזה:","מה נשתנה הלילה הזה מכל הלילות שבכל הלילות אנו מטבילין פעם אחת הלילה הזה שתי פעמים: מתקיף לה רבא אטו כל יומא לא סגיא דלא מטבלא חדא זימנא אלא אמר רבא הכי קתני שבכל הלילות אין אנו חייבין לטבל אפילו פעם אחת הלילה הזה שתי פעמים","מתקיף לה רב ספרא חיובא לדרדקי אלא אמר רב ספרא הכי קתני אין אנו מטבילין אפילו פעם אחת הלילה הזה שתי פעמים:","מתחיל בגנות ומסיים בשבח: מאי בגנות רב אמר מתחלה עובדי עבודת גלולים היו אבותינו [ושמואל] אמר עבדים היינו","אמר ליה רב נחמן לדרו עבדיה עבדא דמפיק ליה מריה לחירות ויהיב ליה כספא ודהבא מאי בעי למימר ליה אמר ליה בעי לאודויי ולשבוחי א\"ל פטרתן מלומר מה נשתנה פתח ואמר עבדים היינו:","\u0001מתני׳\u0002 רבן גמליאל היה אומר כל שלא אמר"],[[0,"אף כאן בפרוסה","לברך על אכילת מצה ושתי שלימות מייתי משום ברכת המוציא דלא גרע משאר ימים טובים שצריך לבצוע על שתי ככרות שלימות ובוצע מאחת מהשלימות:"],[0,"אף כאן הוא מסיק ואשתו אופה","כדי שלא תחמיץ:"],[1,"משום קפא","שרף החזרת קשה ויש בו ארס:"],[1,"קפא דחסא חמא","מי שאכל חזרת וחלה בשביל הקפא יאכל צנון וירפא:"],[1,"קפא דחמא כרתי","מי שאכל צנון וקשה לו יאכל כרתי:"],[1,"חמימי","ישתה מים חמין:"],[1,"קפא דכולהו חמימי","ארס של כל ירקות חמין רפואה להן:"],[2,"זכר לתפוח","שהיו יולדות בניהן שם בלא עצב שלא יכירו בהן מצריים דכתיב תחת התפוח עוררתיך (שיר השירים ח׳:ה׳):"],[2,"לסמוכיה","להטיל ולכתוש בו הרבה כדי שיהיה עב וצריך לקהוייה להטיל בו תפוחים ויין ומילתא דאית בו קיוהא:"],[2,"צריך לקהוייה","זכר לתפוח וצריך לסמוכיה זכר לטיט:"],[3,"תבלין","ירקות שמטילין בחרוסת זכר לתבן וחרוסת שכותשים בו הדק זכר לטיט:"],[3,"תגרי חרך","חנוונים היושבים אצל חלונותיהם ומוכרין כמו מציץ מן החרכים (שם ב):"],[4,"מתני' וכאן הבן שואל אביו","כאן במזיגת כוס שני הבן שואל את אביו מה נשתנה עכשיו שמוזגין כוס שני קודם אכילה:"]],[[0,"מה דרכו של עני בפרוסה","נראה דגם המוציא צריך לברך על הפרוסה וכן משמע בפ' כיצד מברכין (ברכות דף לט:) דקאמר הכל מודים לענין פסח שמניח פרוסה בתוך השלימות ובוצע פי' אפילו למ\"ד מברך על השלימה ופוטר את הפתיתין מודה לענין פסח דאינו מברך על השלימה אלא על הפרוסה משום מה דרכו של עני כו' ומניחה בתוך השלימה כדי שיהא נראה שבצע על השלימה ומשמע דלענין המוציא קמיירי וקאמר בתר הכי א\"ר חייא בר אבא בשבת חייב לבצוע על שני ככרות שנאמר לקטו לחם משנה ועיקר מילתיה דר' חייא בר אבא בפרק כל כתבי (שבת ד' קיז:) אלא להכי מייתי התם אחר פסח לומר שצריך שם מצה שלישית משום לחם משנה וחייב לבצוע על שתי ככרות בין בשבת בין בי\"ט דאי לאו הכי למה הביא שם מילתיה דר' חייא וכן פסק רב אלפס דצריך לבצוע על שתי ככרות ביום טוב והטעם לפי שהיה לחם משנה יורד בערבי ימים טובים וקשה שאנו מתפללים באתה קדשת וברכתו מכל הימים וקדשתו מכל הזמנים ואמר (במכילתא פרש' בשלח) במן ברכו במן קדשו משמע בי\"ט היה מן יורד וכן היה נוהג ה\"ר מנחם מיוני וה\"ר יום טוב שהיו מברכין הכל על הפרוסה אך ר\"י היה מברך המוציא על השלימה והדר על אכילת מצה על הפרוסה ובוצע משתיהן יחד וכן עמא דבר ולכך עושין על השלישית כריכה כדי לקיים מצוה בשלשתן:"],[2,"צריך לסמוכיה וצריך לקהוייה","ובירושלמי אמר אית דעבדי זכר לדם ומשום הכי קרי ליה טיבולו במשקה וכן עמא דבר לסמוכי ובשעת אכילה מקלשין אותו ביין וחומץ ובתשובת הגאונים מפרש לעשות חרוסת בפירות שנדמה לכנסת ישראל בשיר השירים תחת התפוח עוררתיך כפלח הרמון התאנה חנטה אמרתי אעלה בתמר אגוז אל גנת אגוז ושקדים על שם ששקד הקב\"ה על הקץ:"],[3,"תגרי חרך שבירושלים","משמע דהלכה כר' אלעזר בר' צדוק וגם בספרים כתב ר' יוסי ונימוקו עמו וכן עשה ה\"ר יוסף בסדרו חרוסת זכר לטיט:"],[5,"הלילה הזה מרור","הא דלא אמר כולו מרור משום דאכלינן שאר ירקות בטיבול ראשון:"],[5,"כולו צלי","רב חסדא מוקי לה באלו דברים (לעיל פסחים דף ע.) כבן תימא דאמר חגיגה הבאה עם הפסח אינה נאכלת אלא צלי ואע\"ג דקאמר התם ואמר רב חסדא ובפרקין ליתיה דרך הגמרא כן:"]]],[["שלשה דברים אלו בפסח לא יצא ידי חובתו ואלו הן פסח מצה ומרור פסח על שום שפסח המקום על בתי אבותינו במצרים [שנאמר (שמות יב, כז) ואמרתם זבח פסח הוא לה' אשר פסח וגו']","מצה על שום שנגאלו אבותינו ממצרים [שנאמר (שמות יב, לט) ויאפו את הבצק אשר הוציאו ממצרים וגו'] מרור על שום שמררו המצריים את חיי אבותינו במצרים שנאמר [(שמות א, יד) וימררו את חייהם וגו']","בכל דור ודור חייב אדם לראות את עצמו כאילו הוא יצא ממצרים שנאמר (שמות יג, ח) והגדת לבנך ביום ההוא לאמר בעבור זה עשה ה' לי בצאתי ממצרים","לפיכך אנחנו חייבים להודות להלל לשבח לפאר לרומם להדר לברך לעלה ולקלס למי שעשה לאבותינו ולנו את כל הנסים האלו הוציאנו מעבדות לחרות מיגון לשמחה ומאבל ליום טוב ומאפלה לאור גדול ומשעבוד לגאולה ונאמר לפניו הללויה","עד היכן הוא אומר בש\"א עד אם הבנים שמחה ובה\"א עד חלמיש למעינו מים וחותם בגאולה ר\"ט אומר אשר גאלנו וגאל את אבותינו ממצרים ולא היה חותם","רבי עקיבא אומר כן ה' אלהינו ואלהי אבותינו יגיענו למועדים ולרגלים אחרים הבאים לקראתנו לשלום שמחים בבנין עירך וששים בעבודתך ונאכל שם (מן הפסחים ומן הזבחים) כו' עד בא\"י גאל ישראל:","\u0001גמ׳\u0002 אמר רבא צריך שיאמר ואותנו הוציא משם אמר רבא מצה צריך להגביה ומרור צריך להגביה בשר א\"צ להגביה ולא עוד אלא שנראה כאוכל קדשים בחוץ","אמר רב אחא בר יעקב סומא פטור מלומר הגדה כתיב הכא בעבור זה וכתיב התם (דברים כא, כ) בננו זה מה להלן פרט לסומא אף כאן פרט לסומין","איני והאמר מרימר שאלתינהו לרבנן דבי רב יוסף מאן דאמר אגדתא בי רב יוסף אמרו רב יוסף מ\"ד אגדתא בי רב ששת אמרו רב ששת קסברי רבנן מצה בזמן הזה דרבנן","מכלל דרב אחא בר יעקב סבר מצה בזמן הזה דאורייתא והא רב אחא בר יעקב הוא דאמר מצה בזמן הזה דרבנן קסבר כל דתקון רבנן כעין דאורייתא תיקון","לרב ששת ולרב יוסף נמי הא ודאי כל דתקון רבנן כעין דאורייתא תיקון","הכי השתא בשלמא התם מדהוה ליה למיכתב בננו הוא וכתיב בננו זה ש\"מ פרט לסומין הוא דאתא אבל הכא אי לאו בעבור זה מאי לכתוב אלא בעבור מצה ומרור הוא דאתא:","לפיכך אנחנו חייבין:"],[[6,"גמ' צריך להגביה","כשהוא אומר מצה זו שאנו אוכלין:"],[6,"בשר אין מגביה","כשהוא אומר פסח שהיו אבותינו (במצרים) אוכלים לא יגביה הבשר שהוא זכר לפסח:"],[6,"","ה\"ג בשר אינו צריך להגביה ולא עוד אלא שנראה כמקדיש כו':"],[6,"אין צריך להגביה","דהא לא מצי למימר פסח זה:"],[8,"רב יוסף ורב ששת","מאורי עינים היו:"],[9,"הא הוא דאמר","בסופא דהאי פירקא (דף קכ.) אחד זה ואחד זה דרבנן:"]],[[0,"ואמרתם זבח פסח הוא","פי' באמירה שצריך לומר פסח זה שאנו אוכלין ואיתקש מצה ומרור לפסח וצ\"ל נמי מצה זו מרו' זה:"],[3,"לפיכך אנחנו כו'","י\"א שבע הודאות ולא יותר כנגד ז' רקיעים:"],[3,"ה\"ג ונאמר לפניו שירה חדשה וכן נודה לך שיר חדש על גאולתנו","דהכי תניא במכילתא כל השירות לשון נקבה חוץ משירה דלעתיד דלשון זכר כלומר שהנקבה יש לה צער לידה אף כל הנסים יש אחריהם צער חוץ מלעתיד שאין אחריה צער וכן יסד הפייט בזולת אי פתרוס שירות אלה לשון נקבה מיוסדים כי תשועתם כיולדה וגו' תוקף שיר אחרון כזכרים לא יולדים שירו לה' שיר חדש כו' וגרסינן שם מן הזבחים ומן הפסחים שחגיגת ארבעה עשר נאכלת קודם לפסח לפי שהפסח נאכל על השובע:"],[4,"וחותם בגאולה","ת\"ק לא פי' כיצד ופליגי במילתיה ר\"ט ור\"ע ר' טרפון אינו חותם בברוך שלא היה מאריך בדברי בקשה ולא היה אומר אלא הודאה ור\"ע סבר דחותם בה בברוך לפי שמאריך בדברי בקשה ואומר כן ה' אלהינו יגיענו כו' וקי\"ל (עירובין דף מו:) הלכה כר' עקיבא מחבירו וכן מצינו בסנהדרין (דף כא.) גבי לא ירבה לו נשים ובריש חזקת הבתים (ב\"ב דף כח.) דפליגי תנאי במילתיה דתנא קמא:"]]],[["א\"ר חסדא א\"ר יוחנן הללויה וכסיה וידידיה אחת הן רב אמר כסיה ומרחביה אחת הן רבה אמר מרחביה בלבד","איבעיא להו מרחב יה לרב חסדא מאי תיקו","איבעיא להו ידידיה לרב מאי ת\"ש דאמר רב ידידיה נחלק לשנים לפיכך ידיד חול יה קודש","איבעיא להו הללויה לרב מאי ת\"ש דאמר רב חזינא תילי דבי חביבא דכתיב בהו הללו בחד גיסא ויה בחד גיסא","ופליגא דריב\"ל דאמר ריב\"ל מאי הללויה הללוהו בהלולים הרבה","ופליגא דידיה אדידיה דאמר ריב\"ל בעשרה מאמרות של שבח נאמר ספר תהלים בניצוח בנגון במשכיל במזמור בשיר באשרי בתהלה בתפלה בהודאה בהללויה גדול מכולן הללויה שכולל שם ושבח בבת אחת","אמר רב יהודה אמר שמואל שיר שבתורה משה וישראל אמרוהו בשעה שעלו מן הים והלל זה מי אמרו נביאים שביניהן תקנו להן לישראל שיהו אומרין אותו על כל פרק ופרק ועל כל צרה וצרה שלא תבא עליהן ולכשנגאלין אומרים אותו על גאולתן","תניא היה ר\"מ אומר כל תושבחות האמורות בספר תהלים כלן דוד אמרן שנאמר (תהלים עב, כ) כלו תפלות דוד בן ישי אל תיקרי כלו אלא כל אלו","הלל זה מי אמרו רבי יוסי אומר אלעזר בני אומר משה וישראל אמרוהו בשעה שעלו מן הים וחלוקין עליו חביריו לומר שדוד אמרו ונראין דבריו מדבריהן אפשר ישראל שחטו את פסחיהן ונטלו לולביהן ולא אמרו שירה","ד\"א פסלו של מיכה עומד בבכי וישראל אומרים את ההלל:","ת\"ר כל שירות ותושבחות שאמר דוד בספר תהלים ר\"א אומר כנגד עצמו אמרן רבי יהושע אומר כנגד ציבור אמרן וחכ\"א יש מהן כנגד ציבור ויש מהן כנגד עצמו האמורות בלשון יחיד כנגד עצמו האמורות בלשון רבים כנגד ציבור","ניצוח וניגון לעתיד לבא משכיל על ידי תורגמן לדוד מזמור מלמד ששרתה עליו שכינה ואחר כך אמר שירה מזמור לדוד מלמד שאמר שירה ואחר כך שרתה עליו שכינה","ללמדך שאין השכינה שורה לא מתוך עצלות ולא מתוך עצבות ולא מתוך שחוק ולא מתוך קלות ראש ולא מתוך דברים בטלים אלא מתוך דבר שמחה של מצוה שנאמר (מלכים ב ג, טו) ועתה קחו לי מנגן והיה כנגן המנגן ותהי עליו יד ה'","אמר רב יהודה אמר רב וכן לדבר הלכה אמר רב נחמן וכן לחלום טוב","איני והאמר רב גידל אמר רב כל ת\"ח היושב לפני רבו ואין שפתותיו נוטפות מר תכוינה שנאמר (שיר השירים ה, יג) שפתותיו שושנים נוטפות מור עובר אל תקרי שושנים אלא ששונים אל תקרי מור עובר אלא מר עבר","לא קשיא הא ברבה הא בתלמידא","ואי בעית אימא הא והא ברבה ולא קשיא הא מקמי דפתח והא לבתר דפתח כי הא דרבה מקמי דפתח להו לרבנן אמר מילתא דבדיחותא ובדחו רבנן ולבסוף יתיב באימתא ופתח בשמעתא","ת\"ר הלל זה מי אמרו ר\"א אומר משה וישראל אמרוהו בשעה שעמדו על הים הם אמרו (תהלים קטו, א) לא לנו ה' לא לנו משיבה רוח הקודש ואמרה להן (ישעיהו מח, יא) למעני למעני אעשה רבי יהודה אומר יהושע וישראל אמרוהו בשעה שעמדו עליהן מלכי כנען הם אמרו לא לנו ומשיבה וכו'","רבי אלעזר המודעי אומר דבורה וברק אמרוהו בשעה שעמד עליהם סיסרא הם אמרו לא לנו ורוח הקודש משיבה ואומרת להם למעני למעני אעשה ר' אלעזר בן עזריה אומר חזקיה וסייעתו אמרוהו בשעה שעמד עליהם סנחריב הם אמרו לא לנו ומשיבה וכו' רבי עקיבא אומר חנניה מישאל ועזריה אמרוהו בשעה שעמד עליהם נבוכדנצר הרשע הם אמרו לא לנו ומשיבה וכו' רבי יוסי הגלילי אומר מרדכי ואסתר אמרוהו בשעה שעמד עליהם המן הרשע הם אמרו לא לנו ומשיבה וכו'","וחכמים אומרים נביאים שביניהן תיקנו להם לישראל שיהו אומרים אותו על כל פרק ופרק ועל כל צרה וצרה שלא תבא עליהם לישראל ולכשנגאלין אומרים אותו על גאולתן:","אמר רב חסדא הללויה סוף פירקא רבה בר רב הונא אמר הללויה ריש פירקא אמר רב חסדא חזינא להו לתילי דבי רב חנין בר רב דכתיב בהו הללויה באמצע פירקא אלמא מספקא ליה","אמר רב חנין בר רבא הכל מודים (תהלים קמה, כא) בתהלת ה' ידבר פי ויברך כל בשר שם קדשו לעולם ועד (הללויה) הללויה דבתריה ריש פירקא (תהלים קיב, י) רשע יראה וכעס שניו יחרק ונמס תאות רשעים תאבד הללויה דבתריה ריש פירקא (תהלים קלה, ב) ושעומדים בבית ה' הללויה דבתריה ריש פירקא","קראי מוסיפין אף את אלו (תהלים קי, ז) מנחל בדרך ישתה על כן ירים ראש הללויה דבתריה ריש פירקא (תהלים קיא, י) ראשית חכמה יראת ה' שכל טוב לכל עושיהם הללויה דבתריה ריש פירקא","נימא כתנאי עד היכן הוא אומר בית שמאי אומרים עד (תהלים קיג, ט) אם הבנים שמחה ובית הלל אומרים עד (תהלים קיד, ח) חלמיש למעינו מים ותניא אידך עד היכן הוא אומר בית שמאי אומרים עד (תהלים קיד, א) בצאת ישראל ממצרים ובית הלל אומרים עד (תהלים קטו, א) לא לנו ה' לא לנו"],[[0,"אחת היא","כלומר תיבה אחת היא ואין התיבה נחלקת לשנים:"],[3,"הללו בהך גיסא","בסוף שיטה ויה בתחלת שיטה האחרת:"],[6,"שיר שבתורה","אז ישיר משה:"],[6,"ועל כל צרה שלא תבא עליהם","לישנא מעליא הוא דנקט כלומר שאם חס ושלום תבוא צרה עליהן ויושעו ממנה אומרים אותו על גאולתן כגון חנוכה:"],[7,"כל תפלות","כל מזמורים הפותחים בתפלה כגון תפלה לעני כי יעטוף (תהילים ק״ב:א׳):"],[8,"אפשר ישראל שוחטין את פסחיהן","מיציאת מצרים ועד דוד לא אמרו עליו הלל:"],[9,"ד\"א פסלו של מיכה עומד","בימי דוד בבכי באותו מקום וישראל אומרים הלל שכתוב בו כמוהם יהיו עושיהם וגו' אלא ודאי על הים נאמר תחלה ושוב לא פסק:"],[11,"ניצוח וניגון לעתיד לבא","מקום שנאמר למנצח בנגינות מלעתיד הוא מדבר:"],[11,"ע\"י מתורגמן","הוא אומר ואחר מפרש:"],[17,"יהושע וכל ישראל אמרוהו","כלומר אף יהושע וכל ישראל אמרוהו:"],[20,"הללויה","כולהו דבספר תהלים:"],[22,"קראי מוסיפין","בעלי מקרא מוסיפין אף אלו:"]],[[20,"ה\"ג שעומדים בבית ה' בחצרות בית אלהינו הללויה דבתריה ריש פירקא","ולא גרסינן העומדים בבית ה' בלילות דאם כן ה\"ל למינקט יברכך ה' מציון שזהו פסוק למעלה מהללויה ולא ה\"ל למינקט שלשה פסוקים למעלה לכך נראה דגרסינן כדפרישית ולפי זה אנו צריכין לומר בו הללויה הללו את שם ה' הללו עבדי ה' שעומדים בבית ה' וגו' שלמעלה מזה אינו תחלת המזמור דלא יתכן שיהיה המזמור שני פסוקים ועוד דאמרי' במדרש קמ\"ז מזמורים יש בספר תהלים כנגד שנות יעקב אלא הוא סופו של שיר המעלות הנה ברכו וגו' ואתי שפיר דקאמרינן לקמן רב אחא בר יעקב דמתחיל הלל הגדול מכי יעקב בחר לו יה דהוי תחלת המזמור דבע\"א לא יתכן שהיה מתחיל הלל מאמצע המזמור:"]]],[["מאי לאו בהא קמיפלגי למ\"ד עד אם הבנים שמחה סבר הללויה ריש פירקא ומאן דאמר עד בצאת ישראל סבר הללויה סוף פירקא","רב חסדא מתרץ לטעמיה דכולי עלמא סברי הללויה סוף פירקא מ\"ד עד בצאת ישראל שפיר ומאן דאמר עד אם הבנים שמחה עד ועד בכלל","ונימא עד הללויה וכי תימא דלא ידעינן הי הללויה ונימא הללויה של אם הבנים שמחה קשיא","רבה בר רב הונא מתרץ לטעמיה דכולי עלמא הללויה ריש פירקא מאן דאמר עד אם הבנים שמחה שפיר ומאן דאמר עד בצאת ישראל סבר עד ולא עד בכלל","ונימא עד הללויה וכי תימא דלא ידעינן הי הללויה ונימא עד הללויה שבצאת ישראל קשיא:","וחותם בגאולה: אמר רבא ק\"ש והלל גאל ישראל דצלותא גואל ישראל מ\"ט דרחמי נינהו","אמר רבי זירא דקידושא אשר קדשנו במצותיו וצונו דצלותא קדשנו במצותיך מ\"ט דרחמי נינהו","אמר רב אחא בר יעקב וצריך שיזכיר יציאת מצרים בקידוש היום כתיב הכא (דברים טז, ג) למען תזכור את יום וכתיב התם (שמות כ, ז) זכור את יום השבת לקדשו","אמר רבה בר שילא דצלותא מצמיח קרן ישועה דאפטרתא מגן דוד","(שמואל ב ז, ט) ועשיתי לך שם גדול כשם הגדולים תני רב יוסף זהו שאומרים מגן דוד","א\"ר שמעון בן לקיש (בראשית יב, ב) ואעשך לגוי גדול זהו שאומרים אלהי אברהם ואברכך זהו שאומרים אלהי יצחק ואגדלה שמך זהו שאומרים אלהי יעקב","יכול יהו חותמין בכולן ת\"ל והיה ברכה בך חותמין ואין חותמין בכולן","אמר רבא אשכחתינא לסבי דפומבדיתא דיתבי וקאמרי בשבתא בין בצלותא בין בקידושא מקדש השבת ביומא טבא בין בצלותא ובין בקידושא מקדש ישראל והזמנים ואמינא להו אנא אדרבה דצלותא בין בשבתא בין ביומא טבא מקדש ישראל בקידושא דשבתא מקדש השבת ביומא טבא מקדש ישראל והזמנים","ואנא אמינא טעמא דידי וטעמא דידכו טעמא דידכו שבת דקביעא וקיימא בין בצלותא ובין בקידושא מקדש השבת יומא טבא דישראל הוא דקבעי ליה דקמעברי ירחי וקבעי לשני מקדש ישראל והזמנים","טעמא דידי צלותא דברבים איתא מקדש ישראל קידוש דביחיד איתא בשבת מקדש השבת ביום טוב מקדש ישראל והזמנים","ולא היא צלותא ביחיד מי ליתיה וקידושא ברבים מי ליתיה ורבא סבר זיל בתר עיקר","עולא בר רב נחית קמיה דרבא אמר כסבי דפומבדיתא ולא א\"ל ולא מידי אלמא הדר ביה רבא רב נתן אבוה דרב הונא בריה דרב נתן נחית קמיה דרב פפא אמר כסבי דפומבדיתא ושבחיה רב פפא","אמר רבינא אנא איקלע לסורא קמיה דמרימר ונחית קמיה שלוחא דציבורא ואמר כסבי דפומבדיתא והוו משתקי ליה כולי עלמא אמר להו שבקוהו הילכתא כסבי דפומבדיתא ולא הוו משתקו ליה:","\u0001מתני׳\u0002 מזגו לו כוס שלישי מברך על מזונו רביעי גומר עליו את הלל ואומר עליו ברכת השיר בין הכוסות הללו אם רוצה לשתות ישתה בין שלישי לרביעי לא ישתה:","\u0001גמ׳\u0002 א\"ל רב חנן לרבא ש\"מ ברכת המזון טעונה כוס א\"ל ארבע כסי תיקנו רבנן דרך חירות כל חד וחד נעביד ביה מצוה:","רביעי גומר עליו את ההלל ואומר עליו ברכת השיר:"],[[3,"קסבר עד ועד בכלל","ואי אמינא עד בצאת סברי עלמא דאף בצאת בכלל משום הכי אמר עד אם הבנים שמחה ותו לא:"],[3,"[עד ולא עד בכלל]","ואי הוה אמינא עד אם הבנים הוה משמע עד אם הבנים ולא אם הבנים בכלל:"],[7,"","ה\"ג כתיב הכא למען תזכור את יום צאתך וגו' וכתיב התם זכור את יום השבת לקדשו:"],[9,"כשם הגדולים","כאברהם כיצחק ויעקב:"],[14,"דברבים איתא","משום כבוד רבים אומר מקדש ישראל:"]],[[7,"למען תזכור את יום צאתך מארץ מצרים","לכך קבעו זכר ליציאת מצרים ושמעתי מהר\"מ שיש במדרש לפי שבמצרים עבדו בהם בישראל בפרך ופר\"ך בא\"ת ב\"ש וג\"ל שהם מלאכות ארבעים חסר אחת וכשנגאלו ממצרים הזהירם על השבת לשבות מאות' ל\"ט מלאכות:"],[18,"רביעי אומר עליו הלל הגדול","רביעי גרסי' ולא גרסינן חמישי ולה\"ר יוסף טוב עלם שכתב בסדרו קימעא לשתות מים יכנס אם חולה הוא או איסטניס ואי בעי משתיא חמרא משום אונס לומר בחמישי הלל הגדול ישתנס תימה כיון שאוסר לשתות איך תיקנו כוס חמישי הא ארבע כוסות תיקנו ולא חמישי וכן מה שאוסר לשתות אפי' מים הא לא מבטלי טעם מצה דאפילו אחר הפסח לא אסר לקמן רק מיני מיכלא אבל מיני מישתיא אפילו יין לא מצינן לאסור והא דאמר בין שלישי לרביעי לא ישתה מפרש בירושלמי שלא ישתכר ושלא יוכל לומר הלל וכן פסק רבי' שמואל לקמן דכל שתיה מותרת ואפי' לפי המפרשים בין שלישי לרביעי לא ישתה שלא יבטל טעם מצה מ\"מ במים לא מיירי אלא ביין דומיא בין ראשון לשני ישתה דמיירי ביין כי היכי דניגרריה לליביה כדאמרי' לעיל [פסחים דף קח.] ומיהו רוב עמא דבר לשתות וגם רב אלפס התיר מים ולא אסר רק יין:"]]],[["מאי ברכת השיר רב יהודה אמר יהללוך ה' אלהינו ורבי יוחנן אמר נשמת כל חי ת\"ר רביעי גומר עליו את ההלל ואומר הלל הגדול דברי ר\"ט וי\"א (תהלים כג, א) ה' רועי לא אחסר","מהיכן הלל הגדול רבי יהודה אומר (תהלים קלו, א) מהודו עד (תהלים קלז, א) נהרות בבל ורבי יוחנן אומר משיר המעלות עד נהרות בבל רב אחא בר יעקב אמר (תהלים קלה, ד) מכי יעקב בחר לו יה עד נהרות בבל","ולמה נקרא שמו הלל הגדול א\"ר יוחנן מפני שהקב\"ה יושב ברומו של עולם ומחלק מזונות לכל בריה","א\"ר יהושע בן לוי הני עשרים וששה הודו כנגד מי כנגד כ\"ו דורות שברא הקב\"ה בעולמו ולא נתן להם תורה וזן אותם בחסדו","אמר רב חסדא מאי דכתיב (תהלים קלו, א) הודו לה' כי טוב הודו לה' שגובה חובתו של אדם בטובתו עשיר בשורו ואת עני בשיו יתום בביצתו אלמנה בתרנגולתה","א\"ר יוחנן קשין מזונותיו של אדם כפליים כיולדה דאילו ביולדה כתי' (בראשית ג, טז) בעצב ובמזונות כתי' (בראשית ג, יז) בעצבון","(א\"ר) יוחנן קשין מזונותיו של אדם יותר מן הגאולה דאילו בגאולה כתיב (בראשית מח, טז) המלאך הגואל אותי מכל רע מלאך בעלמא ואילו במזונות כתיב (בראשית מח, טו) האלהים הרועה אותי","א\"ר יהושע בן לוי בשעה שאמר הקב\"ה לאדם (בראשית ג, יח) וקוץ ודרדר תצמיח לך זלגו עיניו דמעות אמר לפניו רבש\"ע אני וחמורי נאכל באבוס אחד כיון שאמר לו (בראשית ג, יט) בזעת אפך תאכל לחם נתקררה דעתו","אמר ר\"ש בן לקיש אשרינו אם עמדנו בראשונה ועדיין לא פלטינן מינה דקא אכלינן עיסבי דדברא","אמר רב שיזבי משמיה דרבי אלעזר בן עזריה קשין מזונותיו של אדם כקריעת ים סוף דכתיב (תהלים קלו, כה) נותן לחם לכל בשר וסמיך ליה לגוזר ים סוף לגזרים","אמר ר\"א בן עזריה קשין נקביו של אדם כיום המיתה וכקריעת ים סוף שנאמר (ישעיהו נא, יד) מהר צועה להפתח וכתיב בתרי' רוגע הים ויהמו גליו","ואמר רב ששת משום ר\"א בן עזריה כל המבזה את המועדות כאילו עובד ע\"ז שנאמר (שמות לד, יז) אלהי מסכה לא תעשה לך וכתיב בתריה את חג המצות תשמור","ואמר רב ששת משום ר\"א בן עזריה כל המספר לשון הרע וכל המקבל לשון הרע וכל המעיד עדות שקר בחבירו ראוי להשליכו לכלבים שנאמר (שמות כב, ל) לכלב תשליכון אותו וכתיב בתריה (שמות כג, א) לא תשא שמע שוא וקרי ביה לא תשיא","וכי מאחר דאיכא הלל הגדול אנן מ\"ט אמרינן האי משום שיש בו ה' דברים הללו יציאת מצרים וקריעת ים סוף ומתן תורה ותחיית המתים וחבלו של משיח","יציאת מצרים דכתי' (תהלים קיד, א) בצאת ישראל ממצרים וקריעת ים סוף דכתיב (תהלים קיד, ג) הים ראה וינוס מתן תורה דכתי' (תהלים קיד, ד) ההרים רקדו כאילים תחיית המתים דכתיב (תהלים קטז, ט) אתהלך לפני ה'","חבלו של משיח דכתיב (תהלים קטו, א) לא לנו ה' לא לנו וא\"ר יוחנן לא לנו ה' לא לנו זו שעבוד מלכיות איכא דאמרי אמר רבי יוחנן לא לנו ה' לא לנו זו מלחמת גוג ומגוג","רב נחמן בר יצחק אמר מפני שיש בו מילוט נפשות של צדיקים מגיהנם שנא' (תהלים קטז, ד) אנה ה' מלטה נפשי חזקיה אמר מפני שיש בו ירידתן של צדיקים לכבשן האש ועלייתן ממנו","ירידתן דכתיב לא לנו ה' לא לנו אמר חנניה כי לשמך תן כבוד אמר מישאל על חסדך ועל אמיתך אמר עזריה למה יאמרו הגוים אמרו כולן","עלייתן מכבשן האש דכתיב (תהלים קיז, א) הללו את ה' כל גוים אמר חנניה שבחוהו כל האומים אמר מישאל כי גבר עלינו חסדו אמר עזריה ואמת ה' לעולם הללויה אמרו כולן","ויש אומרים ואמת ה' לעולם גבריאל אמרו בשעה שהפיל נמרוד הרשע את אברהם אבינו לתוך כבשן האש אמר גבריאל לפני הקדוש ברוך הוא רבש\"ע ארד ואצנן ואציל את הצדיק מכבשן האש אמר לו הקב\"ה אני יחיד בעולמי והוא יחיד בעולמו נאה ליחיד להציל את היחיד ולפי שהקב\"ה אינו מקפח שכר כל בריה אמר תזכה ותציל שלשה מבני בניו","דרש ר\"ש השלוני בשעה שהפיל נבוכדנצר הרשע חנניה מישאל ועזריה לתוך כבשן האש עמד יורקמו שר הברד לפני הקב\"ה אמר לפניו רבש\"ע ארד ואצנן את הכבשן ואציל לצדיקים הללו מכבשן האש אמר לו גבריאל אין גבורתו של הקב\"ה בכך שאתה שר ברד והכל יודעין שהמים מכבין את האש אלא אני שר של אש ארד ואקרר מבפנים"],[[0,"","ה\"ג רביעי גומר עליו את ההלל ואומר עליו הלל הגדול:"],[2,"שהקדוש ברוך הוא יושב ברומו של עולם כו'","דכתיב הודו לאל השמים נותן לחם לכל בשר והיינו דבר גדול:"],[4,"עשיר בשורו","מפסידו ממון [ומכפר] על גופו:"],[10,"קשין נקביו של אדם","כשהוא עצור כיום המיתה:"]],[[0,"מאי ברכת השיר רב יהודה אמר יהללוך","וקמ\"ל דאפילו במקום שלא נהגו לברך אחריו בלילי פסח צריך לברך דאי נהגו פשיטא א\"נ דאפילו במקום שנהגו ה\"א דוקא בימים אבל בלילה אין צריך לברך קא משמע לן:"],[0,"רבי יוחנן אמר נשמת כל חי","נראה ה\"פ אף נשמת כל חי אחר יהללוך דאי לא תימא הכי אנן כמאן עבדינן וקורא נשמת כל חי ברכת השיר לפי שבשבתות אומרים אותו אחר פסוקי דזמרה ורבינו חיים כהן לא היה חותם ביהללוך כי אם בנשמת לבדו משום דלישנא דברכת השיר משמע חדא ברכה:"],[1,"מהודו עד על נהרות בבל","וכן אנו עושים ורננו צדיקים בה' אינו מן המזמור:"]]],[["ואקדיח מבחוץ ואעשה נס בתוך נס אמר לו הקב\"ה רד באותה שעה פתח גבריאל ואמר ואמת ה' לעולם","ר' נתן אומר ואמת ה' לעולם דגים שבים אמרוהו כדרב הונא דאמר רב הונא ישראל שבאותו הדור מקטני אמנה היו וכדדרש רבה בר מרי מאי דכתיב (תהלים קו, ז) וימרו על ים בים סוף מלמד שהמרו ישראל באותה שעה ואמרו כשם שאנו עולין מצד אחד כך מצריים עולים מצד אחר","אמר לו הקב\"ה לשר של ים פלוט אותן ליבשה אמר לפניו רבש\"ע כלום יש עבד שנותן לו רבו מתנה וחוזר ונוטל ממנו אמר לו אתן לך אחד ומחצה שבהן","אמר לו רבש\"ע יש עבד שתובע את רבו אמר לו נחל קישון יהא לי ערב מיד פלט אותן ליבשה ובאו ישראל וראו אותן שנאמר (שמות יד, ל) וירא ישראל את מצרים מת על שפת הים","מאי אחד ומחצה שבהן דאילו בפרעה כתיב (שמות יד, ז) שש מאות רכב בחור ואילו בסיסרא כתיב (שופטים ד, ג) תשע מאות רכב ברזל","כי אתא סיסרא [אתא עלייהו בדקרי דפרזלא הוציא הקב\"ה עליהם כוכבים ממסילותם דכתיב] (שופטים ה, כ) מן שמים נלחמו הכוכבים כיון דנחיתו כוכבי שמים עלייהו אקדירו הני דקרי דפרזלא נחיתו לאקרורי למיסחי נפשייהו בנחל קישון","אמר לו הקב\"ה לנחל קישון לך והשלם ערבונך מיד גרפם נחל קישון והשליכן לים שנאמר (שופטים ה, כא) נחל קישון גרפם נחל קדומים מאי נחל קדומים נחל שנעשה ערב מקדם באותה שעה פתחו דגים של ים ואמרו ואמת ה' לעולם","אמר רבי שמעון בן לקיש מאי דכתיב (תהלים קיג, ט) מושיבי עקרת הבית אמרה כנסת ישראל לפני הקב\"ה רבש\"ע שמוני בניך כחולדה זו הדרה בעיקרי בתים:","דרש רבא מאי דכתיב (תהלים קטז, א) אהבתי כי ישמע ה' אמרה כנסת ישראל רבש\"ע אימת אני אהובה לפניך בזמן שתשמע קול תחנוני דלותי ולי יהושיע אמרה כנסת ישראל לפני הקב\"ה רבש\"ע אע\"פ שדלה אני במצות לך אני ולי נאה להושיע","אמר רב כהנא כשחלה רבי ישמעאל בר' יוסי שלח לו ר' אמור לנו שנים ושלשה דברים שאמרת לנו משום אביך","שלח לו כך אמר אבא מאי דכתיב (תהלים קיז, א) הללו את ה' כל גוים אומות העולם מאי עבידתייהו ה\"ק הללו את ה' כל גוים אגבורות ונפלאות דעביד בהדייהו כל שכן אנו דגבר עלינו חסדו","(אמר לו) ועוד (חדא) עתידה מצרים שתביא דורון למשיח כסבור אינו מקבל מהם אמר לו הקב\"ה למשיח קבל מהם אכסניא עשו לבניי במצרים מיד (תהלים סח, לב) יאתיו חשמנים מני מצרים","נשאה כוש ק\"ו בעצמה ומה הללו שנשתעבדו בהן כך אני שלא נשתעבדתי בהן לא כ\"ש אמר לו הקב\"ה קבל מהם מיד (תהלים סח, לב) כוש תריץ ידיו לאלהים","נשאה מלכות [רומי] הרשעה ק\"ו בעצמה ומה הללו שאין אחיהן כך אנו שאנו אחיהן לא כ\"ש אמר לו הקדוש ברוך הוא לגבריאל (תהלים סח, לא) גער חית קנה געור חיה וקנה לך עדה","דבר אחר געור חית קנה שדרה בין הקנים דכתיב (תהלים פ, יד) יכרסמנה חזיר מיער וזיז שדי ירענה","אמר רבי חייא בר אבא אמר רבי יוחנן געור בחיה שכל מעשיה נכתבין בקולמוס אחד (תהלים סח, לא) עדת אבירים בעגלי עמים ששחטו אבירים כעגלים שאין להם בעלים","(תהלים סח, לא) מתרפס ברצי כסף שפושטין יד לקבל ממון ואין עושין רצון בעלים (תהלים סח, לא) פיזר עמים קרבות יחפצון מי גרם להם לישראל שיתפזרו לבין אומות העולם קריבות שהיו חפצין בהן","ועוד שלח לו ג' מאות וששים וחמשה שווקים בכרך גדול של רומי וכל אחד ואחד היו בו שלש מאות וששים וחמשה בירניות וכל בירנית ובירנית היו בו שלש מאות וששים וחמשה מעלות וכל מעלה ומעלה היו בו כדי לזון את כל העולם כולו","אמר רבי (ישמעאל) לרבי ואמרי לה (לר' ישמעאל בר יוסי) הני למן לך ולחברך ולחברותך שנאמר (ישעיהו כג, יח) סחרה ואתננה קודש לה' לא יאצר ולא יחסן כי ליושבים לפני ה' יהיה וגו'","מאי לא יאצר תני רב יוסף לא יאצר זה בית אוצר ולא יחסן זה בית גניזה מאי כי ליושבים לפני ה' אר\"א"],[[0,"ואקדיח מבחוץ","לשרוף את הזורקים אותן לתוך האור דכתיב (דניאל ג) גובריא אילך די הסיקו לשדרך מישך ועבד נגו קטיל הימון שביבא דנורא:"],[0,"ואמת ה' לעולם","שקיים לי דברו ושמר לי הבטחתו שהבטיחני להציל מבני בניו של אברהם:"],[2,"שנתן לו רבו מתנה","פרנסה לדגים:"],[5,"","ה\"ג כיון דנחיתו כוכבי שמיא עלייהו נחיתו לאקורי נפשייהו בנחל קישון:"],[6,"ואמת ה' לעולם","ששילם לנו מתנותינו מחיל פרעה להתפרנס ממנו:"],[7,"שמוני בניך","מרוב חטאותם בגלות:"],[7,"כחולדה זו שדרה בעיקרי בתים","והיינו עקרת הבית:"],[10,"אומות העולם מאי עבידתייהו","לשבוחי משום דגבר עלינו חסדו הא עלן לשבוחי:"],[10,"אגבורות ונפלאות","דחזיתו שעשה לי:"],[13,"וקנה","עדת ישראל בין הקנים ביער:"],[14,"חזיר מיער","זה אדום שכתוב בה (שם ז) אכלה ומדקה ושארא ברגלה רפסה וזה דרכו של חזיר:"],[15,"שכל מעשיה נכתבים בקולמוס אחד","כלו' פה אחד להם להרע:"],[16,"מתרפס","מתיר פס פושט יד:"],[16,"ברצי","כלומר מתנים עם ישראל לעשות רצונם בשוחד שהם מקבלים ואין מקיימין דבריהם:"]],[[5,"מן שמים נלחמו הכוכבי' ממסילותם","במקומן היו עומדים וראשן מגיע עד לארץ וכן פירש\"י בנימוקי מקרא ותימה למ\"ד בפ' מי שהיה (לעיל פסחים דף צד.) כל העולם כולו תחת כוכב א' עומד האיך ירדו הכוכבים הלא מאחד נתמלא העולם י\"ל דלא איירי אלא בכוכבים של גלגל שהן מזלות קבועים אבל שאר כוכבים קטנים הם:"]]],[["זה המכיר מקום חבירו בישיבה איכא דאמרי אמר ר\"א זה המקבל פני חבירו בישיבה","מאי למכסה עתיק (יומין) זה המכסה דברים שכיסה עתיק יומין ומאי נינהו סתרי תורה ואיכא דאמרי זה המגלה דברים שכיסה עתיק יומין מאי נינהו טעמי תורה","אמר רב כהנא משום רבי ישמעאל ברבי יוסי מאי דכתיב (תהלים ד, א) למנצח מזמור לדוד זמרו למי שנוצחין אותו ושמח","בא וראה שלא כמדת הקב\"ה מדת בשר ודם בשר ודם מנצחין אותו ועצב אבל הקב\"ה נוצחין אותו ושמח שנאמר (תהלים קו, כג) ויאמר להשמידם לולי משה בחירו עמד בפרץ לפניו","אמר רב כהנא משום רבי ישמעאל בר' יוסי אמר ר\"ש בן לקיש משום רבי יהודה נשיאה מאי דכתיב (יחזקאל א, ח) וידי אדם מתחת כנפיהם ידו כתיב זה ידו של הקדוש ברוך הוא שפרוסה תחת כנפי החיות כדי לקבל בעלי תשובה מיד מדת הדין","אמר רב יהודה אמר שמואל כל כסף וזהב שבעולם יוסף לקטו והביאו למצרים שנאמר (בראשית מז, יד) וילקט יוסף את כל הכסף הנמצא אין לי אלא שבארץ מצרים ושבארץ כנען בשאר ארצות מנין תלמוד לומר (בראשית מא, נז) וכל הארץ באו מצרימה","וכשעלו ישראל ממצרים העלוהו עמהן שנאמר (שמות יב, לו) וינצלו את מצרים רב אסי אמר עשאוה כמצודה זו שאין בה דגן רבי שמעון אמר כמצולה שאין בה דגים","והיה מונח עד רחבעם בא שישק מלך מצרים ונטלו מרחבעם שנאמר (מלכים א יד, כה) ויהי בשנה החמישית למלך רחבעם עלה שישק מלך מצרים [על ירושלים] ויקח את אוצרות בית ה' ואת אוצרות בית המלך בא זרח מלך כוש ונטלו משישק","בא אסא ונטלוהו מזרח מלך כוש ושיגרו להדרימון בן טברימון באו בני עמון ונטלום מהדרימון בן טברימון בא יהושפט ונטלו מבני עמון והיה מונח עד אחז","בא סנחריב ונטלו מאחז בא חזקיה ונטלו מסנחריב והיה מונח עד צדקיה באו כשדיים ונטלוהו מצדקיה באו פרסיים ונטלוהו מכשדיים באו יוונים ונטלוהו מפרסיים באו רומיים ונטלוהו מיד יוונים ועדיין מונח ברומי:","אמר רבי חמא (בר) חנינא שלש מטמוניות הטמין יוסף במצרים אחת נתגלה לקרח ואחת נתגלה לאנטונינוס בן אסוירוס ואחת גנוזה לצדיקים לעתיד לבא","(קהלת ה, יב) עושר שמור לבעליו לרעתו אמר רבי שמעון בן לקיש זו עשרו של קרח (שנאמר) (דברים יא, ו) ואת כל היקום אשר ברגליהם א\"ר אלעזר זה ממונו של אדם שמעמידו על רגליו א\"ר לוי משאוי שלש מאות פרדות לבנות היו מפתחות בית גנזיו של קרח וכולהו אקלידי וקליפי דגלדא:","(דיא\"ש אדי\"ש כשד\"ך מאוד\"ך סימן) א\"ר שמואל בר נחמני א\"ר יונתן (תהלים קיח, כא) אודך כי עניתני אמר דוד אבן מאסו הבונים היתה לראש פנה אמר ישי מאת ה' היתה זאת אמרו אחיו זה היום עשה ה' אמר שמואל","אנא ה' הושיעה נא אמרו אחיו אנא ה' הצליחה נא אמר דוד ברוך הבא בשם ה' אמר ישי ברכנוכם מבית ה' אמר שמואל אל ה' ויאר לנו אמרו כולן אסרו חג בעבותים אמר שמואל אלי אתה ואודך אמר דוד אלהי ארוממך אמרו כולן:","תנן התם מקום שנהגו"],[[0,"זה המכיר מקום חבירו בישיבה","שיודע לומר זה מקום מיושב לפלוני וזה של פלוני דהואיל ומכיר הוא מקום כולם רגיל הוא לישב שם תמיד:"],[1,"סתרי תורה","מעשה מרכבה ומעשה בראשית:"],[2,"למנצח","מדלא כתיב לנצח משמע שנותן כח לבריות לנצחו:"],[3,"לולי משה בחירו","אלמא משתבח ביה קרא במשה וקרי ליה בחירו משום דהשיב חמתו מהשחית אלמא שמח הוא בכך:"],[4,"מפני מדת הדין","שמקטרגת ואומרת לא תקבלם והוא מקבלם בסתר:"],[6,"כמצודה זו","שפורסים לעופות לצוד ואין בה דגן ואין עוף נפנה אליה:"],[7,"","מלחמתו של זרח במצרים גמרא אבל מלחמת זרח באסא קראי:"],[8,"ושיגרו להדרימון","מלך ארם לעזור לו על בעשא מלך ישראל וקראי נינהו ומלחמת יהושפט בעמונים קראי ודרך הראשונים להביא גנזיהם עמהם במלחמתם כדי שימשך לבם אחר ממונם ולא יברחו:"],[11,"שמעמידו על רגליו","שמשמח לבו:"],[11,"אקלידי","מפתחות:"],[11,"וקולפי","פותחות שקורין בלעז שרדור\"א (שירידור\"א: מנעול) :"],[11,"דגלדי","של מרצופים של עור שנושאים על סוסים וחמורים וגמלים:"],[12,"אבן מאסו הבונים","כלומר דוד שמימיו רועה צאן היה ונעשה ראש ונפלאת בעינינו לשון רבים אמרו אחיו:"],[12,"זה היום עשה ה'","שמואל היה מתנבא עליהם שסופן לגיל ולשמוח שיושיעם מיד אויביהם:"],[13,"הושיעה נא אמרו אחיו","כלומר על ידי דוד ודוד אמר הצליחה נא שיצליח במלכותו:"],[13,"אסרו חג בעבותים","הביאו זבחים ושלמים הרבה לשמוח:"],[13,"ברכנוכם אמר שמואל","שיברך כולם כלומר מברכין אנו אתכם:"],[13,"לנו","לשון רבים:"],[13,"אסרו חג בעבותים","הביאו זבחים ושלמים הרבה לשמוח:"]],[[6,"כמצודה שאין בה דגן","דרך ציידי עופות להשים דגן במצודה ודריש וינצלו וינצלו כי למ\"ד מתחלפת בדל\"ת במקומות הרבה:"]]],[["לכפול יכפול לפשוט יפשוט לברך אחריו יברך הכל כמנהג המדינה אמר אביי לא שנו אלא לאחריו אבל לפניו [מצוה] לברך דא\"ר יהודה אמר שמואל כל המצות מברך עליהן עובר לעשייתן","מאי משמע דהאי עובר לישנא דאקדומי הוא א\"ר נחמן בר יצחק דכתיב (שמואל ב יח, כג) וירץ אחימעץ דרך הככר ויעבור את הכושי אביי אמר מהכא (בראשית לג, ג) והוא עבר לפניהם איכא דאמרי מהכא (מיכה ב, יג) ויעבור מלכם לפניהם וה' בראשם","תניא רבי כופל בה דברים רבי אלעזר בן פרטא מוסיף בה דברים מאי מוסיף אמר אביי מוסיף לכפול מאודך למטה","דרש רב עוירא זימנין א\"ל משמיה דרב וזימנין א\"ל משמיה דרב (אשי) מאי דכתיב (בראשית כא, ח) ויגדל הילד ויגמל עתיד הקב\"ה לעשות סעודה לצדיקים ביום שיגמל חסדו לזרעו של יצחק לאחר שאוכלין ושותין נותנין לו לאברהם אבינו כוס של ברכה לברך","ואומר להן איני מברך שיצא ממני ישמעאל אומר לו ליצחק טול וברך אומר להן איני מברך שיצא ממני עשו אומר לו ליעקב טול וברך אומר להם איני מברך שנאשתי שתי אחיות בחייהן שעתידה תורה לאוסרן עלי","אומר לו למשה טול וברך אומר להם איני מברך שלא זכיתי ליכנס לארץ ישראל לא בחיי ולא במותי אומר לו ליהושע טול וברך אומר להן איני מברך שלא זכיתי לבן דכתיב יהושע בן נון (דברי הימים א ז, כז) נון בנו יהושע בנו","אומר לו לדוד טול וברך אומר להן אני אברך ולי נאה לברך שנאמר (תהלים קטז, יג) כוס ישועות אשא ובשם ה' אקרא:","\u0001מתני׳\u0002 אין מפטירין אחר הפסח אפיקומן:","\u0001גמ׳\u0002 מאי אפיקומן אמר רב שלא יעקרו מחבורה לחבורה","ושמואל אמר כגון אורדילאי לי וגוזלייא לאבא ורב חנינא בר שילא ורבי יוחנן (אמר) כגון תמרים קליות ואגוזים תניא כוותיה דרבי יוחנן אין מפטירין אחר הפסח כגון תמרים קליות ואגוזים","אמר רב יהודה אמר שמואל אין מפטירין אחר מצה אפיקומן תנן אין מפטירין אחר הפסח אפיקומן אחר הפסח הוא דלא אבל לאחר מצה מפטירין","לא מיבעיא קאמר לא מיבעיא אחר מצה דלא נפיש טעמייהו אבל לאחר הפסח דנפיש טעמיה ולא מצי עבוריה לית לן בה קמשמע לן","נימא מסייע ליה הסופגנין והדובשנין והאיסקריטין אדם ממלא כריסו מהן ובלבד שיאכל כזית מצה באחרונה באחרונה אין"],[[0,"לכפול","כל ההלל:"],[2,"מתני' מפטירין","לשון הנפטר מחבירו כשנפטרין מן הסעודה מביאין מיני המתיקה: גמ' ארדילאי לי כגון אני שרגיל לאכול כמהין ופטריות לאחר סעודתי:"],[2,"כופל דברים","מעט היה כופל כגון מברוך הבא ולמטה:"],[5,"נון בנו וגו'","ממשפחת אפרים בן יוסף חשיב ואזיל עד יהושע ולא משכח ברא ליהושע:"],[7,"מתני' מפטירין","לשון הנפטר מחבירו כשנפטרין מן הסעודה מביאין מיני המתיקה:"],[9,"","גמ' ארדילאי לי כגון אני שרגיל לאכול כמהין ופטריות לאחר סעודתי:"],[9,"וגוזליא לאבא","לרב שהיה רגיל לאכול גוזלים לאחר סעודתו ולשון אפיקומן הוציאו והביאו מיני מתיקה:"],[10,"אין מפטירין אחר מצה אפיקומן","שצריך לאכול מצה בגמר הסעודה זכר למצה הנאכלת עם הפסח וזו היא מצה הבצועה שאנו אוכלין באחרונה לשם חובת מצה אותה שלאחר אכילה ועל כרחינו אנו מברכין על אכילת מצה בראשונה (הואיל ו) [אע\"פ שאינה] באה לשם חובה כדאמר רב חסדא לעיל (פסחים דף קטו.) גבי מרור דלאחר שמילא כריסו הימנו היאך חוזר ומברך עליו הכי נמי גבי מצה הלכך תרוייהו מברך ברישא והדר אכיל מצה באחרונה בלא ברכה אבל לא מרור דלאו חובה הוא:"]],[[0,"אבל לפניו מצוה לברך","לפי מה שפירש לעיל דהפסוקים לא הוו הפסק וברכה אחרונה היא חתימת הראשונה לא יתכן כאן דאיך יברך לפניו ולא יחתום אחריו מהר\"י:"],[8,"אמר רב שלא יעקרו מחבורה לחבורה","רב מוקי למתניתין כדר' יהודה דסבר דאין הפסח נאכל בשני מקומות והכי אוקימנא סתמא פרק כיצד צולין (לעיל פסחים ד' פו.) שתי חבורות שהיו אוכלות בבית אחד אלו הופכין פניהם ואוכלין ואלו הופכין פניהם ואוכלין והשמש באמצע פירוש משום היכרא וכשהשמש עומד למזוג קופץ את פיו עד שמגיע אצל חבורתו ומוקי לה בגמרא כרבי יהודה והיינו דוקא בפסח אבל מצה לא אשכחן בשום דוכתא דליתסר בשתי מקומות ואי משום דאתקש לפסח להא על כרחיך לא איתקש דאי לא תימא הכי ליפרך ממתני' לרב דאין מפטירין אחר הפסח אפיקומן הא אחר מצה מפטירין ולא מצי לשנויי כדמשני לשמואל דלגבי שני מקומות לא הוי רבותא פסח טפי ממצה אלא ודאי רב לא איירי אלא בפסח והא דקאמרינן לקמן אביי הוה יתיב קמיה דרבה והוה קא מנמנם פי' הקונטרס לקמן אע\"ג דלא הוי בזמן הפסח הא איתקש מצה לפסח ולא נהירא ובירושלמי מפרש לה גבי תענית דאמרינן פ\"ק דתענית ישן אסור לאכול ולא שנו אלא ישן ממש אבל מתנמנם לא ורבה הוה מתנמנם ובעי למיסר בתר הכי וקמייתי ראיה מפסח דכי היכי דפסח לא חשיב נמנום בעלמא כשינה מעליא לענין שני מקומות ה\"נ לא חשיב נמנום לענין תענית דלמחר לאיתסורי באכילה בתר הכי:"]]],[["בראשונה לא לא מיבעיא קאמר לא מיבעיא בראשונה דקאכיל לתיאבון אבל באחרונה דילמא אתי למיכל אכילה גסה אימא לא קמ\"ל","מר זוטרא מתני הכי אמר רב יוסף אמר רב יהודה אמר שמואל מפטירין אחר המצה אפיקומן נימא מסייע ליה אין מפטירין אחר הפסח אפיקומן אחר הפסח דלא אבל אחר מצה מפטירין","לא מיבעיא קאמר לא מיבעיא אחר מצה דלא נפיש טעמיה אבל לאחר פסח אימא לא קמ\"ל","מיתיבי הסופגנין והדובשנין והאיסקריטין אדם ממלא כריסו מהן ובלבד שיאכל (אכילת) כזית מצה באחרונה באחרונה אין בראשונה לא","לא מיבעיא קאמר לא מיבעיא בראשונה דקאכיל לתיאבון אבל באחרונה דאתי למיכלה אכילה גסה אימא לא קמ\"ל:","אמר רבא מצה בזמן הזה דאורייתא ומרור דרבנן ומאי שנא מרור דכתיב (במדבר ט, יא) על מצות ומרורים בזמן דאיכא פסח יש מרור ובזמן דליכא פסח ליכא מרור","מצה נמי הא כתיב על מצות ומרורים מצה מיהדר הדר ביה קרא (שמות יב, יח) בערב תאכלו מצות ורב אחא בר יעקב אמר אחד זה ואחד זה דרבנן","אלא הכתיב בערב תאכלו מצות ההיא מיבעי ליה לטמא ושהיה בדרך רחוקה דס\"ד אמינא כיון דפסח לא אכלי מצה ומרור נמי לא ניכול קמ\"ל","ורבא אמר לך טמא ושהיה בדרך רחוקה לא צריך קרא דלא גרעי מערל ובן נכר דתניא (שמות יב, מח) כל ערל לא יאכל בו בו אינו אוכל אבל אוכל במצה ומרור","ואידך כתיב בהאי וכתיב בהאי וצריכי","תניא כוותיה דרבא (דברים טז, ח) ששת ימים תאכל מצות וביום השביעי עצרת לה' אלהיך מה שביעי רשות אף ששת ימים רשות","מאי טעמא הוי דבר שהיה בכלל ויצא מן הכלל ללמד לא ללמד על עצמו יצא אלא ללמד על הכלל כולו יצא","יכול אף לילה הראשון רשות תלמוד לומר על מצות ומרורים יאכלוהו","אין לי אלא בזמן שבית המקדש קיים בזמן שאין בית המקדש קיים מנין ת\"ל בערב תאכלו מצות הכתוב קבעו חובה:","\u0001מתני׳\u0002 ישנו מקצתן יאכלו כולן לא יאכלו"],[[0,"בראשונה לא","דאין אדם רשאי לאכול כלום אחר מצת חובה:"],[10,"מה שביעי רשות","דכתיב וביום השביעי עצרת דלא כתיב תאכלו מצות שהרי הוציאו מן הכלל אף ששת ימים רשות שאם רוצה יכול לאכול בשר בלא לחם או להתענות:"],[14,"מתני' כולם לא יאכלו","אם התחילו לאכול פסחם וישנו ועדיין לא אכלו כל פסחם לא יאכלו דנראין כאוכלי פסחם בשתי חבורות או בזמן הזה שאין פסח אם ישנו כולם:"]],[[0,"באחרונה אין בראשונה לא","פי' בראשונה בלא אחרונה לא כגון דלית ליה אלא כזית מצה ותו לא דטוב לאוכלו על השובע ולהיות טעם מצה בפיו אבל ודאי אי אית ליה מצה לכל סעודתו טוב לו לאכול מצה בתחלה לתיאבון ולברך עליה ואח\"כ בגמר סעודתו יאכל כזית מצה ויהיה טעם מצה בפיו ועיקר מצוה על הראשונה שהיא באה לתיאבון וגם יהא לבסוף טעם מצה בפיו באותו כזית אחרון ואפילו אם עיקר מצוה באחרונה אין זה תימה אם אנו מברכין על הראשונה כדי לפטור המצה של אחרונה שהרי אין לברך על האחרונה משום שלאחר שמילא כריסו הוא אבל יכול הוא לברך על הראשונה ותיפטר האחרונה שהיא עיקר המצוה כדפרישית לעיל לרב חסדא גבי תרי טיבולי דמרור וכן צ\"ל להלל שהיה כורך מצה ופסח בסוף הסעודה והכי הוי אכיל מצה דאורייתא אם כן בתחלת סעודה היה מברך על המצה ואוכל דמועלת אותה ברכה לברכת מצה עם הפסח שבסוף ומיהו לההיא פירוש' דלעיל דלרב חסדא בעי לחזר על שאר ירקות לטיבול ראשון כדי שיברך על המרור בטיבול שני א\"כ ה\"נ יחזר כמו כן על הסופגנין לאכול בתחלה כדי שיברך על אכילת מצה לבסוף מיהו לפי' אחר שגם לרב חסדא אין צריך לחזר על שאר ירקות אלא מברך על המרור בטיבול ראשון ובאותה ברכה יצא בטיבול שני ה\"נ יברך על מצה דמתחלה ויצא בשל מצות מצה שלבסוף:"],[1,"מפטירין אחר מצה אפיקומן","וא\"ת אחר הפסח מאי טעמא אין מפטירין הא נפיש טעמיה טפי ממצה יש לומר כדמפרש בירושלמי דמשום הכי נאכל על השובע שלא יבא לידי שבירת עצם וכתיב (שמות י״ב:מ״ו) ועצם לא תשברו בו ומש\"ה אין אוכלין שום דבר וא\"ת הא במנחה נמי אמרי' בתמורה (דף כג.) ובמנחות (דף כא:) דנאכלת על השובע וליכא למימר האי טעמא י\"ל דהתם ה\"ט שלא יצא משלחן רבו רעב אבל במצה לא שייך האי טעמא דלאו משלחן רבו הויא כולי האי וחגיגה הבאה עם הפסח אע\"ג דאיכא למ\"ד דאית בה משום שבירת עצם ואפ\"ה אינה נאכלת על השובע היינו משום דפסח בן שנתו הוא ורכיך וחיישינן לשבירת עצם אבל חגיגה לא ומאן דאמר אין מפטירין אחר מצה ופסח אם כן לא ס\"ל כטעם הירושלמי אלא סבר דבעינן שיהא טעם מצה ופסח בפיו:"],[6,"רב אחא בר יעקב אמר אחד זה ואחד זה מדרבנן","צ\"ע בההיא סוגיא דפרק כל שעה (לעיל פסחים דף כח:) דמשמע בין לר' יהודה בין לר\"ש סבירא להו דהוי דאורייתא מר נפקא לן מעליו מדכתיב שבעת ימים תאכל עליו מצות דעליו מיותר לומר דעליו של פסח הוא חייב לאכול מצות ומר נפקא לן מבערב תאכלו מצות כדרבא וצ\"ל דההיא פלוגתא אליבא דרבא ולא כרב אחא בר יעקב ומ\"מ תימה דרבי יהודה מצריך קרא לטמא ושהיה בדרך רחוקה וערל ובן נכר כסברת רב אחא בר יעקב דלית הילכתא כוותיה ואנן קיימא לן כרבי יהודה לגבי רבי שמעון:"],[8,"כל בן נכר לא יאכל בו בו אינו אוכל","אין לפרש בו אינו חייב לאכול דהא ודאי חייב לאכול דהא חייב בכל המצות אלא שאינו רוצה ונראה לפרש דמיירי בישראל מומר בשעת שחיטה וחזר ועשה תשובה וקאמר אף על גב דישראל מעליא הוא כיון שלא נמנה עליו בשעת שחיטה שוב אינו אוכל בו אבל אוכל הוא במצה ובמרור וערל היינו שמתו אחיו מחמת מילה וחייב בכל המצות ומקיים כולן אלא שאינו בפסח ובפרק מי שהיה טמא (לעיל פסחים דף צו.) גרס תרוייהו כל ערל לא יאכל בו כל בן נכר לא יאכל בו למה לי ומשני צריכי דאי אתמר ערל משום דמאיס כו' לכאורה משמע דאיצטריך גופיה דקרא ולא נהירא דלמה לי צריכותא אפילו דמו להדדי לגמרי וכי מזהירין מן הדין פשיטא דתרוייהו צריכי למכתב אלא אדיוקא דקראי קאי דדייקינן בו הוא דאינו אוכל אבל אוכל הוא במצה ובמרור קיימא הך צריכותא והכי מיפרשא התם צריכא דאי אשמעינן כלומר תרוייהו צריכי לדיוקא דקרא אבל אוכל הוא במצה ובמרור דאי אשמעינן ערל משום דלבו לשמים אבל בן נכר אימא לא ואי אשמעינן בן נכר משום דלא מאיס אבל ערל אימא לא ואף על גב דגמרא לא קאמר הכי ליכא למיחש שלא בא להשמיענו אלא שחלוקים זה מזה והוי כאילו צריכי לגופייהו ודכוותה אשכחן בפ\"ק דב\"ק (דף ג.) גבי ושלח דמשמע שן ומשמע רגל כו':"]]],[["ר' יוסי אומר נתנמנמו יאכלו נרדמו לא יאכלו הפסח אחר חצות מטמא את הידים הפגול והנותר מטמאין את הידים:","\u0001גמ׳\u0002 ר' יוסי אומר נתנמנמו יאכלו נרדמו לא יאכלו ה\"ד נתנמנם אמר רב אשי נים ולא נים תיר ולא תיר כגון דקרי ליה ועני ולא ידע לאהדורי סברא וכי מדכרו ליה מדכר","אביי הוה יתיב קמיה דרבה חזא דקא נמנם א\"ל מינם קא נאים מר א\"ל מינומי קא מנמנם ותנן נתנמנמו יאכלו נרדמו לא יאכלו:","הפסח אחר חצות מטמא את הידים וכו': אלמא מחצות ה\"ל נותר מאן תנא","אמר רב יוסף ר\"א בן עזריה הוא דתניא (שמות יב, ח) ואכלו את הבשר בלילה הזה ר\"א בן עזריה אומר נאמר כאן בלילה הזה ונאמר להלן (שמות יב, יב) ועברתי בארץ מצרים בלילה הזה","מה להלן עד חצות אף כאן עד חצות","אמר לו ר\"ע והלא נאמר חפזון עד שעת חפזון","אם כן מה ת\"ל בלילה יכול יהא נאכל כקדשים ביום ת\"ל בלילה בלילה הוא נאכל ואינו נאכל ביום","ור\"ע האי הזה מאי עביד ליה מיבעי ליה למעוטי לילה אחר הוא דאתא ס\"ד אמינא הואיל ופסח קדשים קלים ושלמים קדשים קלים מה שלמים נאכלים לשני ימים ולילה אחד אף פסח","אוקים לילות במקום ימים ויהא נאכל לשני לילות ויום אחד כתב רחמנא הזה","ור\"א בן עזריה אמר לך (שמות יב, י) מלא תותירו עד בקר נפקא הא","ור\"ע אמר לך אי לא כתב רחמנא הזה הוה אמינא מאי בקר בקר שני ור\"א אמר לך כל היכא דכתב בקר בקר ראשון הוא","אמר רבא אכל מצה בזמן הזה אחר חצות לר\"א בן עזריה לא יצא ידי חובתו פשיטא דכיון דאיתקש לפסח כפסח דמי","מהו דתימא הא אפקיה קרא מהיקישא קמשמע לן דכי אהדריה קרא למילתא קמייתא אהדריה:","הפיגול והנותר מטמא את הידים וכו: רב הונא ורב חסדא חד אמר משום חשדי כהונה וחד אמר משום עצלי כהונה חד אמר כזית וחד אמר כביצה"],[[6,"גמ' עד שעת חפזון","שנבהלו לצאת והיינו עד הבקר:"],[9,"ויום אחד","ט\"ו המפסיק בין הלילות דלא ליהוי נותר עד ט\"ז:"],[13,"הא אפקיה קרא מהיקישא","דפסח דכתיב (שמות יב) (בערב תאכלו מצות) [ששת ימים כו'] ואקשיה בהיקישא דעל מצות ומרורים יאכלוהו (במדבר ט׳:י״א):"],[13,"קמ\"ל דכי אהדריה קרא","(שבעת ימים תאכל מצות) [בערב כו'] (שמות יג) למילתיה קמייתא אהדריה לעמוד במקום הפסח ולאכול עד חצות:"]],[[10,"מלא תותירו עד בקר נפקא","אע\"ג דדרשינן מיניה (לעיל פסחים דף פג:) ליתן לו בקר שני לשריפתו דנפקא לן מהתם דאין שורפין קדשים בי\"ט אית מאן דמפיק ליה בפ\"ב דשבת (דף כד:) ובמכילתין מדוכתא אחרינא:"],[12,"אמר רבא אכל מצה בזמן הזה כו'","יש מפרשים דכך הלכה דהא סתם מתני' כוותיה ואין זה ראיה דהא פרק ב' דמגילה (דף כ:) אשכחן סתמא אחרינא דלא כוותיה דתנן זה הכלל כל דבר שמצותו בלילה כשר כל הלילה לאתויי אכילת פסחים ודלא כר\"א בן עזריה דאמר אכילת פסחים עד חצות היינו ודאי מדאוריית' ובתר הכי פסול למיכל אבל הא דאמרינן הקטר חלבים ואימורים עד חצות כדאמרינן בריש ברכות (דף ב.) לא הוי אלא מדרבנן אפילו לראב\"ע משום הכי אם עיכב להקטיר עד חצות לא נפסל בכך דהא מן התורה היו כשירים עד הבקר וחכמים לא עשו סייג לדבר להביאם לבית הפסול קודם הזמן ובפ' המזבח מקדש (זבחים פו:) נמי מוכח הא דחצות עושה (פיגול) [עיכול] מדרבנן וההוא דבפרק איזהו מקומן (זבחים נז:) דקאמ' דמתני' דהפסח אינו נאכל אלא עד חצות ר\"א בן עזריה היא ופריך ממאי דאורייתא דלמא מדרבנן ור\"ע היא ומשני א\"כ מאי אלא פירוש אי הוה מדרבנן לא ה\"ל למיתני אלא דהא לעיל גבי תודה וחטאת תנא עד חצות ולא תנא אלא דאפילו אירע דעבר על דברי חכמים ולא אכל קודם חצות לא נפסל ואוכלו לאחר חצות כדמשמע פ\"ק דברכות (דף ט.) גבי ק\"ש בההוא מעשה דבאו בניו של ר\"ג מבית המשתה ומ\"מ איכא סייג דעבר על דברי חכמים אם לא אכל קודם חצות וה\"ג התם א\"כ מאי אלא ותו כי הנך מה הנך דאורייתא כלומר מה הנהו דאינו נאכל אלא למנוייו וצלי היינו דאוריית' אף הנך נמי דעד חצות דאורייתא ורבי אלעזר בן עזריה היא [עי' תוס' זבחים נז: ד\"ה ואב\"א ותוס' מגילה כא. דא לאתויי]:"]]],[["חד תני אפיגול וחד תני אנותר","מאן דתני אפיגול משום חשדי כהונה מאן דתני אנותר משום עצלי כהונה","חד אמר כזית וחד אמר כביצה מאן דאמר כזית כאיסורו ומאן דאמר כביצה כטומאתו:","\u0001מתני׳\u0002 בירך ברכת הפסח פטר את של זבח בירך את של זבח לא פטר את של פסח דברי רבי ישמעאל רבי עקיבא אומר לא זו פוטרת זו ולא זו פוטרת זו:","\u0001גמ׳\u0002 כשתמצא לומר לדברי רבי ישמעאל זריקה בכלל שפיכה ולא שפיכה בכלל זריקה","לדברי רבי עקיבא לא שפיכה בכלל זריקה ולא זריקה בכלל שפיכה:"],[[0,"חד תני אפיגול וחד תני אנותר","חד מפרש טעמא דמתניתין מאי טעמא מטמא פיגול את הידים וחד מפרש טעמא דנותר מאי טעמא נותר מטמא את הידים:"],[1,"משום חשדי כהונה","גזרו עליו טומאה שלא יפגלוהו ברצון להפסיד את הבעלים ועוד דשלמים הן ואין לכהן בהן אלא חזה ושוק וישחטם במזיד לשם חטאת כדי לאוכלן כולם ומשום הכי גזרו טומאה:"],[1,"משום עצלי כהונה","שלא יתעצלו באכילתן:"],[2,"חד אמר כזית","מהן מטמא את הידים וח\"א בכביצה:"],[3,"מתני' ברכת הפסח","על אכילת פסחים על של זבח חגיגת ארבעה עשר ומברכין על אכילת שלמים:"],[4,"","שירי דם בזריקה מרחוק דלא איכפת ליה אם נופלים שיריים על היסוד או לא שירי דם הפסח בשפיכה בנחת כדי שיפלו על היסוד:"],[5,"לא שפיכה בכלל זריקה","כלומר שאם נותן פסח בזריקה ושלמים בשפיכה לא עשה כלום וכיון דאין דומין זה לזה במתן דמים אין ברכת האחד פוטרת האחר:"],[5,"","הכי גרסינן במתניתין בירך על הזבח לא פטר את הפסח על הפסח פטר את של זבח דברי ר' ישמעאל והכא גרסינן לדברי ר' ישמעאל זריקה בכלל שפיכה ולא שפיכה בכלל זריקה ופירוש אם נתן פסח בזריקה לא עשה כלום אבל אם נתן שלמים בשפיכה יצא לפיכך ברכת הפסח פוטרת את של שלמים ששלמים בכלל פסח במתן דמים ושל שלמים אינה פוטרת את של פסח לפי שאין פסח במתן דמו בכלל שלמים:"]],[[4,"כשתמצא לומר לדברי ר' ישמעאל זריקה בכלל שפיכה ולא שפיכה בכלל זריקה לדברי ר' עקיבא כו'","אם כן מוכח מכאן דלר' ישמעאל הניתנין בזריקה שנתנן בשפיכה יצא וכן מוכיח נמי כאן דס\"ל דפסח בשפיכה הוא והכי נמי מוכח בפסחים בפרק האשה (דף פט.) דפריך דאלו פסח בשפיכה ושלמים בזריקה ומשני מאי נפקא מינה והתניא מנין לניתנין בזריקה שנתן בשפיכה שיצא כו' אלמא אית ליה תרתי פסח בשפיכה וזריקה בכלל שפיכה דזריקה עומד מרחוק וזורק את הדם ליסוד ושפיכה עומד על היסוד ושופך וקשה דבזבחים פרק בית שמאי (זבחים דף לז.) משמע מאן דאית ליה פסח בשפיכה לא מצי סבר נזרקין שנתנן בשפיכה יצא וכן איפכא מאן דאית ליה נזרקין שנתנן בשפיכה יצא לית ליה פסח בשפיכה דקאמר ודם זבחיך ישפך והא מיבעי ליה לכדתניא מנין לניתנין בזריקה שנתנן בשפיכה יצא ת\"ל ודם זבחיך ישפך ומשני סבר לה כרבי עקיבא דאמר לא זריקה בכלל שפיכה וכו' פי' וההיא דרשא מנין לניתנין בזריקה לר' ישמעאל היא ופריך ואכתי מיבעיא ליה לכדתניא ר' ישמעאל אומר מתוך שנאמר אך בכור שור או בכור כשב וגו' את דמם תזרוק למדנו לבכור שטעון מתן דמים למזבח מעשר ופסח מנין ת\"ל ודם זבחיך ישפך ומשני סבר לה כריה\"ג דאמר פסח נמי בזריקה והדר פריך ליה [ור' ישמעאל] האי קרא מפיק ליה הכי ומפיק ליה הכי וקאמר תרי תנאי אליבא דר' ישמעאל אלמא ההוא תנא דר' ישמעאל דלעיל דנזרקין שנתנן בשפיכה יצא ויליף מדם זבחיך ישפך לית ליה להאי תנא דרבי ישמעאל דיליף מההוא קרא פסח בשפיכה וי\"ל דודאי ר' ישמעאל אית ליה תרתי וניתנין בזריקה שנתנן בשפיכה יצא נפיק ליה מסברא דמה לי זריקה מרחוק ומה לי שפיכה בקרוב קרא כי אתא [לפסח] בשפיכה הוא דאתא והאי דלא משני ליה הכי כדפריך ליה ור' ישמעאל האי קרא היכי מפיק ליה הכי וכו' משום דדרשא של רבי יוסי הגלילי פשוט ליה טפי והתם פי' הקונט' ור' ישמעאל האי קרא דודם זבחיך ישפך מפיק ליה להכי לניתנין בזריקה שנתן בשפיכה יצא וע\"כ ההיא דניתנין לא אתיא כרבי עקיבא דאי אתיא אמאי קאמר רבי עקיבא אין ברכת פסח פוטרת של זבח והלא שלמים בכלל פסח והכל בשפיכה מההיא דניתנין ואי נמי הוה ס\"ל לרבי עקיבא פסח בזריקה כרבי יוסי הגלילי כל שכן דשניהם פוטרין זה את זה ואכתי קדריש ליה לההוא קרא לפסח בשפיכה ומשני תרי תנאי וכו' האי תנא דר' ישמעאל דיליף מודם זבחיך ישפך פסח בשפיכה לית ליה פסח פוטר את הזבח ובהא לא פליג רבי ישמעאל אדרבי עקיבא דהא כיון דדריש מיניה פסח בשפיכה תו לית ליה למילף מיניה דניתנין בזריקה שנתן בשפיכה יצא והאי תנא דר' ישמעאל דיליף מיניה דניתנין בזריקה שנתן בשפיכה יצא לית ליה פסח בשפיכה אלא בזריקה כשלמים מיהו הא סברא דידיה דפליג ארבי עקיבא דפסח עיקר וזבח טפל ע\"כ פסח פוטר את הזבח ולא ברכת זבח את הפסח ובפסחים דירושלמי אמר האי טעמא עכ\"ל וקשה דלעיל הוכחנו מהנהו דפסחים דאית להו תרוייהו וכדכתבינן לעיל ורשב\"ם פירש הכי כשתמצא לומר לדברי ר' ישמעאל זריקה בכלל כו' מתוך דבריו למדנו דקאמר בירך על הפסח וכו' א\"כ ס\"ל דפסח בזריקה ומעתה אייתר ליה ודם זבחיך ישפך לומר דזריקה בכלל שפיכה וכל הנזרקין אם נתנן בשפיכה יצא ול\"ג ושפיכה בכלל זריקה דהא אין שום קרבן דמצותו לכתחלה בשפיכה וקשה ההיא דפ' האשה ור' חיים כהן פי' כשתמצא לומר לדברי ר' ישמעאל זריקה בכלל שפיכה ושפיכה בכלל זריקה כך היא גירסא בספרים ישנים כלומר כל הקרבנות בזריקה ובשפיכה ואין להקפיד וברכת פסחים על עיקר לפטור את הטפל ולא הטפל את העיקר [וקשה] והלא אית ליה נמי דפסחים מצותו בשפיכה דוקא אם כן אין זה זריקה:"]]],[["רבי שמלאי איקלע לפדיון הבן בעו מיניה פשיטא על פדיון הבן אשר קדשנו במצותיו וצונו על פדיון הבן אבי הבן מברך ברוך שהחיינו וקיימנו והגיענו לזמן הזה כהן מברך או אבי הבן מברך","כהן מברך דקמטי הנאה לידיה או אבי הבן מברך דקא עביד מצוה לא הוה בידיה אתא שאיל ביה מדרשא אמרו ליה אבי הבן מברך שתים והילכתא אבי הבן מברך שתים:","\u0001הדרן עלך ערבי פסחים וסליקא לה מסכת פסחים\u0002"],[],[]]]};
